insert into public.categories (id, lettre, titre, resume, icon, position, status) values ('regard', 'A', 'Le regard', 'Les yeux sont une porte du cœur. Ce que l''on regarde, on finit par le désirer.', 'Eye', 0, 'review') on conflict (id) do nothing;
insert into public.categories (id, lettre, titre, resume, icon, position, status) values ('relations', 'B', 'Les relations', 'Des liens qui commencent « innocemment » et éloignent peu à peu d''Allah.', 'HeartCrack', 1, 'review') on conflict (id) do nothing;
insert into public.categories (id, lettre, titre, resume, icon, position, status) values ('reseaux', 'C', 'Les réseaux sociaux', 'Un outil utile devenu, pour beaucoup, un piège pour le temps, le regard et le cœur.', 'Smartphone', 2, 'review') on conflict (id) do nothing;
insert into public.categories (id, lettre, titre, resume, icon, position, status) values ('pudeur', 'D', 'La pudeur', 'La pudeur est une branche de la foi : dans le vêtement, le comportement et le cœur.', 'Shirt', 3, 'review') on conflict (id) do nothing;
insert into public.categories (id, lettre, titre, resume, icon, position, status) values ('comportement', 'E', 'Le comportement', 'La langue, l''orgueil, la jalousie : des péchés du quotidien que l''on ne voit plus.', 'MessageCircleWarning', 4, 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('nur-30', 'An-Nour', 24, '30', 'قُل لِّلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ۚ ذَٰلِكَ أَزْكَىٰ لَهُمْ ۗ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ', 'Dis aux croyants de baisser leurs regards et de préserver leur chasteté. C''est plus pur pour eux. Allah est parfaitement informé de ce qu''ils font.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('nur-31', 'An-Nour', 24, '31', null, 'Et dis aux croyantes de baisser leurs regards, de préserver leur chasteté, et de ne montrer de leurs atours que ce qui en paraît, et qu''elles rabattent leur voile (khimar) sur leurs poitrines… Et repentez-vous tous devant Allah, ô croyants, afin que vous réussissiez.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('nur-15', 'An-Nour', 24, '15', null, '…Vous le considériez comme une chose insignifiante, alors qu''auprès d''Allah c''était énorme.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('nur-19', 'An-Nour', 24, '19', null, 'Ceux qui aiment que la turpitude se propage parmi les croyants auront un châtiment douloureux ici-bas et dans l''au-delà. Allah sait, et vous ne savez pas.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('nur-21', 'An-Nour', 24, '21', null, 'Ô vous qui avez cru ! Ne suivez pas les pas du Diable. Quiconque suit les pas du Diable, [qu''il sache que] celui-ci ordonne la turpitude et le blâmable.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('isra-32', 'Al-Isra', 17, '32', 'وَلَا تَقْرَبُوا الزِّنَىٰ ۖ إِنَّهُ كَانَ فَاحِشَةً وَسَاءَ سَبِيلًا', 'Et n''approchez pas la fornication. C''est vraiment une turpitude, et quel mauvais chemin !', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('isra-36', 'Al-Isra', 17, '36', null, 'Ne poursuis pas ce dont tu n''as aucune connaissance. L''ouïe, la vue et le cœur : sur tout cela, on sera certes interrogé.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('isra-23', 'Al-Isra', 17, '23-24', null, 'Ton Seigneur a décrété : « N''adorez que Lui, et soyez bienfaisants envers vos père et mère. Si l''un d''eux ou tous deux atteignent la vieillesse auprès de toi, ne leur dis point « Fi ! », ne les brusque pas, et adresse-leur des paroles respectueuses. Abaisse pour eux, par miséricorde, l''aile de l''humilité, et dis : « Seigneur, fais-leur miséricorde comme ils m''ont élevé tout petit. »', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('isra-53', 'Al-Isra', 17, '53', null, 'Dis à Mes serviteurs de prononcer les meilleures paroles, car le Diable sème la discorde entre eux. Le Diable est certes pour l''homme un ennemi déclaré.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('ahzab-59', 'Al-Ahzab', 33, '59', null, 'Ô Prophète ! Dis à tes épouses, à tes filles et aux femmes des croyants de ramener sur elles leurs grands voiles (jalabib) : elles en seront plus vite reconnues et éviteront d''être offensées. Allah est Pardonneur et Miséricordieux.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('ahzab-35', 'Al-Ahzab', 33, '35', null, '…les hommes et les femmes qui évoquent souvent Allah : Allah a préparé pour eux un pardon et une énorme récompense.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('araf-26', 'Al-A''raf', 7, '26', null, 'Ô enfants d''Adam ! Nous avons fait descendre sur vous un vêtement pour cacher votre nudité, ainsi que des parures. Mais le vêtement de la piété, voilà ce qui est meilleur.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('araf-23', 'Al-A''raf', 7, '23', 'رَبَّنَا ظَلَمْنَا أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ', 'Ils dirent : « Notre Seigneur, nous avons fait du tort à nous-mêmes. Si Tu ne nous pardonnes pas et ne nous fais pas miséricorde, nous serons très certainement du nombre des perdants. »', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('araf-200', 'Al-A''raf', 7, '200-201', null, 'Et si jamais le Diable t''incite à faire le mal, cherche refuge auprès d''Allah : Il entend et sait tout. Ceux qui craignent Allah, lorsqu''une suggestion du Diable les touche, se rappellent [Allah] et les voilà devenus clairvoyants.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('araf-156', 'Al-A''raf', 7, '156', 'وَرَحْمَتِي وَسِعَتْ كُلَّ شَيْءٍ', '…Et Ma miséricorde embrasse toute chose.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('hujurat-12', 'Al-Hujurat', 49, '12', 'وَلَا يَغْتَب بَّعْضُكُم بَعْضًا', 'Ô vous qui avez cru ! Évitez de trop conjecturer, car une partie des conjectures est péché. N''espionnez pas et ne médisez pas les uns des autres. L''un de vous aimerait-il manger la chair de son frère mort ? Vous en auriez horreur. Craignez Allah : Allah est Celui qui accepte le repentir, Miséricordieux.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('hujurat-11', 'Al-Hujurat', 49, '11', null, 'Ô vous qui avez cru ! Qu''un groupe ne se moque pas d''un autre groupe : ceux-ci sont peut-être meilleurs qu''eux… Ne vous dénigrez pas et ne vous lancez pas mutuellement des sobriquets [injurieux].', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('hujurat-13', 'Al-Hujurat', 49, '13', null, '…Le plus noble d''entre vous, auprès d''Allah, est le plus pieux. Allah est certes Omniscient et Grand Connaisseur.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('luqman-18', 'Luqman', 31, '18', null, 'Et ne détourne pas ton visage des gens [par mépris], et ne foule pas la terre avec arrogance : Allah n''aime pas le présomptueux plein de gloriole.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('mutaffifin-14', 'Al-Mutaffifin', 83, '14', 'كَلَّا ۖ بَلْ ۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُوا يَكْسِبُونَ', 'Pas du tout ! Mais ce qu''ils ont accompli a couvert leurs cœurs (comme une rouille).', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('hadid-16', 'Al-Hadid', 57, '16', null, 'Le moment n''est-il pas venu pour ceux qui ont cru que leurs cœurs s''humilient à l''évocation d''Allah et devant ce qui est descendu de la vérité, et de ne pas être comme ceux qui ont reçu le Livre avant eux : le temps leur a paru long, leurs cœurs se sont endurcis…', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('hadid-20', 'Al-Hadid', 57, '20', null, 'Sachez que la vie présente n''est que jeu, amusement, vaine parure, une course à l''orgueil entre vous et une rivalité dans l''acquisition des richesses et des enfants… Et la vie présente n''est que jouissance trompeuse.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('baqara-74', 'Al-Baqara', 2, '74', null, 'Puis, après cela, vos cœurs se sont endurcis : ils sont comme des pierres, ou plus durs encore…', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('rad-28', 'Ar-Ra''d', 13, '28', 'أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ', '…N''est-ce pas par l''évocation d''Allah que les cœurs se tranquillisent ?', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('rad-11', 'Ar-Ra''d', 13, '11', 'إِنَّ اللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّىٰ يُغَيِّرُوا مَا بِأَنفُسِهِمْ', '…Allah ne modifie pas l''état d''un peuple tant que [les individus qui le composent] ne modifient pas ce qui est en eux-mêmes.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('taha-124', 'Ta-Ha', 20, '124', null, 'Et quiconque se détourne de Mon rappel mènera certes une vie pleine de gêne, et Nous le ressusciterons aveugle le Jour de la Résurrection.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('hashr-19', 'Al-Hashr', 59, '19', null, 'Et ne soyez pas comme ceux qui ont oublié Allah : [Allah] leur a alors fait oublier leurs propres personnes. Ceux-là sont les pervers.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('hashr-10', 'Al-Hashr', 59, '10', 'رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلًّا لِّلَّذِينَ آمَنُوا رَبَّنَا إِنَّكَ رَءُوفٌ رَّحِيمٌ', '« Seigneur, pardonne-nous ainsi qu''à nos frères qui nous ont précédés dans la foi, et ne mets dans nos cœurs aucune rancœur envers ceux qui ont cru. Seigneur, Tu es Compatissant et Très Miséricordieux. »', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('fatir-6', 'Fatir', 35, '6', 'إِنَّ الشَّيْطَانَ لَكُمْ عَدُوٌّ فَاتَّخِذُوهُ عَدُوًّا', 'Le Diable est pour vous un ennemi : prenez-le donc pour ennemi. Il ne fait qu''appeler ses partisans pour qu''ils soient des gens de la Fournaise.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('baqara-268', 'Al-Baqara', 2, '268', null, 'Le Diable vous fait craindre l''indigence et vous ordonne des actions honteuses, tandis qu''Allah vous promet pardon et grâce venant de Lui…', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('nahl-99', 'An-Nahl', 16, '99-100', null, 'Il n''a aucun pouvoir sur ceux qui croient et placent leur confiance en leur Seigneur. Il n''a de pouvoir que sur ceux qui le prennent pour allié…', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('hijr-39', 'Al-Hijr', 15, '39-40', null, '[Iblis] dit : « Seigneur, parce que Tu m''as égaré, je leur embellirai la vie sur terre et les égarerai tous, à l''exception de Tes serviteurs sincères parmi eux. »', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('ibrahim-22', 'Ibrahim', 14, '22', null, 'Et lorsque tout sera accompli, le Diable dira : « …Je n''avais aucune autorité sur vous si ce n''est que je vous ai appelés et que vous m''avez répondu. Ne me faites donc pas de reproches, mais faites-en à vous-mêmes… »', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('ibrahim-7', 'Ibrahim', 14, '7', 'لَئِن شَكَرْتُمْ لَأَزِيدَنَّكُمْ', 'Et lorsque votre Seigneur proclama : « Si vous êtes reconnaissants, très certainement J''augmenterai [Mes bienfaits] pour vous. »', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('yusuf-53', 'Yusuf', 12, '53', null, 'Je ne m''innocente cependant pas, car l''âme incite au mal, à moins que mon Seigneur, par miséricorde, [ne la protège]. Mon Seigneur est certes Pardonneur et Miséricordieux.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('nazi-40', 'An-Nazi''at', 79, '40-41', null, 'Et quant à celui qui aura redouté de comparaître devant son Seigneur et préservé son âme de la passion, le Paradis sera alors son refuge.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('jathiya-23', 'Al-Jathiya', 45, '23', null, 'As-tu vu celui qui a fait de sa passion sa divinité ?…', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('imran-14', 'Al ''Imran', 3, '14', null, 'On a embelli aux gens l''amour des choses qu''ils désirent : femmes, enfants, trésors amassés d''or et d''argent… Tout cela est l''objet de jouissance pour la vie présente, alors que c''est auprès d''Allah qu''il y a le meilleur retour.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('imran-185', 'Al ''Imran', 3, '185', 'كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ', 'Toute âme goûtera la mort. Et c''est seulement au Jour de la Résurrection que vous recevrez votre entière rétribution. Quiconque est écarté du Feu et introduit au Paradis a certes réussi. La vie présente n''est qu''un objet de jouissance trompeuse.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('imran-135', 'Al ''Imran', 3, '135', null, 'Et pour ceux qui, s''ils ont commis une turpitude ou fait du tort à eux-mêmes, se souviennent d''Allah et demandent pardon pour leurs péchés — et qui donc pardonne les péchés sinon Allah ? — et qui ne persistent pas sciemment dans ce qu''ils ont fait.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('imran-134', 'Al ''Imran', 3, '134', null, '…ceux qui dépensent dans l''aisance et dans l''adversité, qui maîtrisent leur colère et pardonnent aux gens. Allah aime les bienfaisants.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('imran-133', 'Al ''Imran', 3, '133', null, 'Et hâtez-vous vers un pardon de votre Seigneur et vers un Paradis large comme les cieux et la terre, préparé pour les pieux.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('imran-159', 'Al ''Imran', 3, '159', null, 'C''est par quelque miséricorde de la part d''Allah que tu as été doux envers eux. Si tu avais été rude et au cœur dur, ils se seraient dispersés loin de toi…', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('imran-31', 'Al ''Imran', 3, '31', null, 'Dis : « Si vous aimez vraiment Allah, suivez-moi : Allah vous aimera alors et vous pardonnera vos péchés. Allah est Pardonneur et Miséricordieux. »', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('imran-8', 'Al ''Imran', 3, '8', 'رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ الْوَهَّابُ', '« Seigneur, ne laisse pas dévier nos cœurs après que Tu nous as guidés, et accorde-nous Ta miséricorde. C''est Toi, certes, le Grand Donateur. »', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('zalzala-7', 'Az-Zalzala', 99, '7-8', 'فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ ۝ وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ', 'Quiconque fait un bien, fût-ce du poids d''un atome, le verra, et quiconque fait un mal, fût-ce du poids d''un atome, le verra.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('zumar-53', 'Az-Zumar', 39, '53', 'قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَىٰ أَنفُسِهِمْ لَا تَقْنَطُوا مِن رَّحْمَةِ اللَّهِ ۚ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا ۚ إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ', 'Dis : « Ô Mes serviteurs qui avez commis des excès à votre propre détriment, ne désespérez pas de la miséricorde d''Allah. Allah pardonne tous les péchés. C''est Lui le Pardonneur, le Très Miséricordieux. »', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('zumar-10', 'Az-Zumar', 39, '10', null, '…Les endurants recevront leur pleine récompense sans compter.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('tahrim-8', 'At-Tahrim', 66, '8', null, 'Ô vous qui avez cru ! Repentez-vous à Allah d''un repentir sincère (tawbatan nasuha). Il se peut que votre Seigneur efface vos méfaits et vous fasse entrer dans des jardins sous lesquels coulent les rivières…', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('tahrim-6', 'At-Tahrim', 66, '6', null, 'Ô vous qui avez cru ! Préservez vos personnes et vos familles d''un Feu dont le combustible sera les hommes et les pierres…', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('furqan-70', 'Al-Furqan', 25, '70', null, '…sauf celui qui se repent, croit et accomplit une bonne œuvre : ceux-là, Allah changera leurs mauvaises actions en bonnes. Allah est Pardonneur et Miséricordieux.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('furqan-27', 'Al-Furqan', 25, '27-29', null, 'Le jour où l''injuste se mordra les deux mains et dira : « Hélas pour moi ! Si seulement j''avais suivi le chemin avec le Messager ! Malheur à moi ! Si seulement je n''avais pas pris un tel pour ami ! Il m''a égaré loin du rappel après qu''il me soit parvenu. »', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('furqan-74', 'Al-Furqan', 25, '74', 'رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا', '« Seigneur, donne-nous, en nos épouses et nos descendants, la joie des yeux, et fais de nous un guide pour les pieux. »', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('hud-114', 'Hud', 11, '114', 'إِنَّ الْحَسَنَاتِ يُذْهِبْنَ السَّيِّئَاتِ', 'Accomplis la prière aux deux extrémités du jour et à certaines heures de la nuit. Les bonnes actions dissipent les mauvaises. Cela est une exhortation pour ceux qui réfléchissent.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('baqara-222', 'Al-Baqara', 2, '222', 'إِنَّ اللَّهَ يُحِبُّ التَّوَّابِينَ وَيُحِبُّ الْمُتَطَهِّرِينَ', '…Allah aime ceux qui se repentent et Il aime ceux qui se purifient.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('nisa-17', 'An-Nisa''', 4, '17', null, 'Allah accueille le repentir de ceux qui font le mal par ignorance et qui se repentent peu après…', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('nisa-110', 'An-Nisa''', 4, '110', null, 'Quiconque agit mal ou fait du tort à lui-même, puis implore le pardon d''Allah, trouvera Allah Pardonneur et Miséricordieux.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('nisa-31', 'An-Nisa''', 4, '31', null, 'Si vous évitez les grands péchés qui vous sont interdits, Nous effacerons vos méfaits de votre compte et Nous vous ferons entrer dans un lieu d''honneur.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('nisa-135', 'An-Nisa''', 4, '135', null, 'Ô vous qui avez cru ! Observez strictement la justice et soyez des témoins [véridiques] pour Allah, fût-ce contre vous-mêmes, contre vos père et mère ou vos proches…', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('nisa-28', 'An-Nisa''', 4, '28', null, 'Allah veut vous alléger [les obligations], car l''homme a été créé faible.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('ankabut-45', 'Al-''Ankabut', 29, '45', 'إِنَّ الصَّلَاةَ تَنْهَىٰ عَنِ الْفَحْشَاءِ وَالْمُنكَرِ', 'Récite ce qui t''est révélé du Livre et accomplis la prière. La prière préserve de la turpitude et du blâmable. Et le rappel d''Allah est ce qu''il y a de plus grand.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('ankabut-69', 'Al-''Ankabut', 29, '69', null, 'Et ceux qui luttent pour Notre cause, Nous les guiderons certes sur Nos sentiers. Allah est en vérité avec les bienfaisants.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('talaq-2', 'At-Talaq', 65, '2-3', 'وَمَن يَتَّقِ اللَّهَ يَجْعَل لَّهُ مَخْرَجًا', '…Et quiconque craint Allah, Il lui donnera une issue favorable, et lui accordera Ses dons par des moyens sur lesquels il ne comptait pas. Et quiconque place sa confiance en Allah, Il lui suffit.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('baqara-152', 'Al-Baqara', 2, '152', 'فَاذْكُرُونِي أَذْكُرْكُمْ وَاشْكُرُوا لِي وَلَا تَكْفُرُونِ', 'Souvenez-vous de Moi, Je Me souviendrai de vous. Soyez-Moi reconnaissants et ne soyez pas ingrats envers Moi.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('baqara-153', 'Al-Baqara', 2, '153', 'إِنَّ اللَّهَ مَعَ الصَّابِرِينَ', 'Ô vous qui avez cru ! Cherchez secours dans l''endurance et la prière. Allah est avec les endurants.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('baqara-286', 'Al-Baqara', 2, '286', 'لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا', 'Allah n''impose à aucune âme une charge supérieure à sa capacité…', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('baqara-201', 'Al-Baqara', 2, '201', 'رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ', '« Seigneur, accorde-nous une belle part ici-bas et une belle part dans l''au-delà, et protège-nous du châtiment du Feu. »', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('baqara-261', 'Al-Baqara', 2, '261', null, 'Ceux qui dépensent leurs biens dans le sentier d''Allah ressemblent à un grain d''où naissent sept épis, chaque épi contenant cent grains. Allah multiplie la récompense à qui Il veut…', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('baqara-165', 'Al-Baqara', 2, '165', null, '…Mais ceux qui ont cru sont les plus ardents en l''amour d''Allah.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('kahf-28', 'Al-Kahf', 18, '28', null, 'Fais preuve de patience [en restant] avec ceux qui invoquent leur Seigneur matin et soir, désirant Sa Face. Et que tes yeux ne se détachent pas d''eux, recherchant le faste de la vie d''ici-bas…', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('zukhruf-67', 'Az-Zukhruf', 43, '67', null, 'Les amis intimes seront, ce jour-là, ennemis les uns des autres, excepté les pieux.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('muminun-1', 'Al-Mu''minun', 23, '1-3', null, 'Bienheureux sont les croyants, ceux qui sont humbles dans leur prière, et qui se détournent des futilités.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('muminun-99', 'Al-Mu''minun', 23, '99-100', null, 'Puis, lorsque la mort vient à l''un d''eux, il dit : « Seigneur ! Fais-moi revenir [sur terre], afin que je fasse du bien dans ce que je délaissais. » Non, c''est simplement une parole qu''il dit. Derrière eux, il y a une barrière (barzakh) jusqu''au jour où ils seront ressuscités.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('maida-8', 'Al-Ma''ida', 5, '8', null, '…Et que la haine pour un peuple ne vous incite pas à être injustes. Pratiquez l''équité : cela est plus proche de la piété.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('anfal-27', 'Al-Anfal', 8, '27', null, 'Ô vous qui avez cru ! Ne trahissez pas Allah et le Messager. Ne trahissez pas sciemment la confiance qu''on a placée en vous.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('anfal-2', 'Al-Anfal', 8, '2', null, 'Les vrais croyants sont ceux dont les cœurs frémissent quand on mentionne Allah, et dont la foi augmente quand Ses versets leur sont récités, et qui placent leur confiance en leur Seigneur.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('humaza-1', 'Al-Humaza', 104, '1', null, 'Malheur à tout calomniateur, diffamateur.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('takathur-1', 'At-Takathur', 102, '1-2', null, 'La course aux richesses vous distrait, jusqu''à ce que vous visitiez les tombes.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('sajda-17', 'As-Sajda', 32, '17', null, 'Aucune âme ne sait ce qu''on a réservé pour eux comme réjouissance pour les yeux, en récompense de ce qu''ils œuvraient.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('qaf-16', 'Qaf', 50, '16-18', null, 'Nous avons effectivement créé l''homme et Nous savons ce que son âme lui suggère, et Nous sommes plus près de lui que sa veine jugulaire… Il ne prononce pas une parole sans avoir auprès de lui un observateur prêt à l''inscrire.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('munafiqun-9', 'Al-Munafiqun', 63, '9', null, 'Ô vous qui avez cru ! Que ni vos biens ni vos enfants ne vous distraient du rappel d''Allah. Et quiconque fait cela, ceux-là sont les perdants.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('anam-120', 'Al-An''am', 6, '120', null, 'Laissez le péché apparent ou caché. Ceux qui acquièrent le péché seront rétribués selon ce qu''ils ont commis.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('najm-32', 'An-Najm', 53, '32', null, 'Ceux qui évitent les grands péchés et les turpitudes, et ne commettent que des fautes légères… Ton Seigneur est immense dans Son pardon…', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('fussilat-34', 'Fussilat', 41, '34', null, 'La bonne action et la mauvaise ne sont pas pareilles. Repousse [le mal] par ce qui est meilleur : alors celui avec qui tu avais une inimitié deviendra tel un ami chaleureux.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('tawba-119', 'At-Tawba', 9, '119', null, 'Ô vous qui avez cru ! Craignez Allah et soyez avec les véridiques.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('saff-2', 'As-Saff', 61, '2-3', null, 'Ô vous qui avez cru ! Pourquoi dites-vous ce que vous ne faites pas ? C''est une grande abomination auprès d''Allah que de dire ce que vous ne faites pas.', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('nahl-90', 'An-Nahl', 16, '90', null, 'Certes, Allah ordonne la justice, la bienfaisance et l''assistance aux proches. Et Il interdit la turpitude, l''acte répréhensible et la rébellion…', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('nisa-54', 'An-Nisa''', 4, '54', null, 'Envient-ils les gens pour ce qu''Allah leur a donné de Sa grâce ?…', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('falaq-5', 'Al-Falaq', 113, '1-5', null, 'Dis : « Je cherche protection auprès du Seigneur de l''aube naissante, contre le mal des êtres qu''Il a créés, contre le mal de l''obscurité quand elle s''approfondit, contre le mal de celles qui soufflent sur les nœuds, et contre le mal de l''envieux quand il envie. »', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('nas-1', 'An-Nas', 114, '1-6', null, 'Dis : « Je cherche protection auprès du Seigneur des hommes, le Souverain des hommes, Dieu des hommes, contre le mal du mauvais conseiller, furtif, qui souffle le mal dans les poitrines des hommes, qu''il soit un djinn ou un être humain. »', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('muzzammil-4', 'Al-Muzzammil', 73, '4', null, '…et récite le Coran lentement et clairement (tartil).', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('muhammad-24', 'Muhammad', 47, '24', null, 'Ne méditent-ils donc pas sur le Coran ? Ou y a-t-il des cadenas sur leurs cœurs ?', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('taghabun-16', 'At-Taghabun', 64, '16', null, 'Craignez Allah donc, autant que vous pouvez, écoutez, obéissez et faites des dépenses [dans le bien]…', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('anbiya-87', 'Al-Anbiya''', 21, '87', 'لَا إِلَٰهَ إِلَّا أَنتَ سُبْحَانَكَ إِنِّي كُنتُ مِنَ الظَّالِمِينَ', '…« Pas de divinité à part Toi ! Gloire à Toi ! J''ai été vraiment du nombre des injustes. »', 'review') on conflict (id) do nothing;
insert into public.quran_verses (id, sourate, sourate_num, ayat, texte_ar, traduction_fr, status) values ('imran-173', 'Al ''Imran', 3, '173', 'حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ', '…« Allah nous suffit ; Il est notre meilleur garant. »', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('intention', 'Les actions ne valent que par les intentions, et chacun n''aura que ce qu''il a eu l''intention de faire…', 'إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ', 'Al-Bukhari n°1 ; Muslim n°1907', 'Sahih (unanimement authentique)', 'Rapporté par ''Umar ibn al-Khattab. Les savants le considèrent comme l''un des fondements de la religion : la valeur d''un acte dépend de l''intention qui l''anime.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('repentants', 'Tout fils d''Adam commet des fautes, et les meilleurs de ceux qui commettent des fautes sont ceux qui se repentent.', null, 'At-Tirmidhi n°2499 ; Ibn Majah n°4251', 'Hasan', 'Rapporté par Anas ibn Malik. Il rappelle que l''erreur fait partie de la nature humaine ; ce qui distingue le croyant, c''est son retour vers Allah.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('point-noir', 'Lorsque le croyant commet un péché, un point noir se forme sur son cœur. S''il se repent, cesse et demande pardon, son cœur est purifié. Mais s''il continue, [le noir] augmente jusqu''à recouvrir son cœur. C''est cela le « ran » qu''Allah a mentionné : « Pas du tout ! Mais ce qu''ils ont accompli a couvert leurs cœurs. »', null, 'At-Tirmidhi n°3334 ; Ibn Majah n°4244', 'Hasan sahih (selon at-Tirmidhi)', 'Rapporté par Abu Hurayra. Ce hadith explique le verset 14 de la sourate Al-Mutaffifin et décrit comment la répétition des péchés affecte progressivement le cœur.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('morceau-chair', '…Certes, il y a dans le corps un morceau de chair : s''il est sain, tout le corps est sain, et s''il est corrompu, tout le corps est corrompu. Certes, c''est le cœur.', null, 'Al-Bukhari n°52 ; Muslim n°1599', 'Sahih', 'Rapporté par an-Nu''man ibn Bashir, à la fin du hadith sur le licite et l''illicite et les choses douteuses.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('regard-ali', 'Ô ''Ali, ne fais pas suivre un regard par un autre regard : le premier t''est pardonné, mais pas le second.', null, 'Abu Dawud n°2149 ; At-Tirmidhi n°2777', 'Hasan', 'Conseil du Prophète ﷺ à ''Ali ibn Abi Talib. Le premier regard involontaire n''est pas reproché ; c''est le fait de le prolonger volontairement qui l''est.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('zina-yeux', 'Allah a prescrit au fils d''Adam sa part de zina qu''il atteindra inévitablement : la zina des yeux est le regard, la zina de la langue est la parole ; l''âme souhaite et désire, et le sexe confirme cela ou le dément.', null, 'Al-Bukhari n°6243 ; Muslim n°2657', 'Sahih', 'Rapporté par Abu Hurayra. Les savants expliquent que le regard, la parole et le désir sont des « portes » qui mènent à la fornication ; d''où l''importance de les fermer.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('bien-ou-silence', 'Que celui qui croit en Allah et au Jour dernier dise du bien ou qu''il se taise.', null, 'Al-Bukhari n°6018 ; Muslim n°47', 'Sahih', 'Rapporté par Abu Hurayra, dans un hadith regroupant plusieurs règles de comportement (honorer le voisin, l''invité…).', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('medisance', '« Savez-vous ce qu''est la médisance ? » Ils dirent : « Allah et Son Messager savent mieux. » Il dit : « C''est que tu mentionnes ton frère par ce qu''il déteste. » On lui dit : « Et si ce que je dis se trouve réellement en lui ? » Il dit : « Si cela se trouve en lui, tu as médit de lui, et si cela ne se trouve pas en lui, tu l''as calomnié. »', null, 'Muslim n°2589', 'Sahih', 'Rapporté par Abu Hurayra. Il donne la définition précise de la médisance (ghiba) et de la calomnie (buhtan).', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('verite', 'Attachez-vous à la véracité, car la véracité guide vers la piété et la piété guide vers le Paradis… Et gardez-vous du mensonge, car le mensonge guide vers la perversité et la perversité guide vers le Feu…', null, 'Al-Bukhari n°6094 ; Muslim n°2607', 'Sahih', 'Rapporté par ''Abd Allah ibn Mas''ud. Il montre que chaque habitude, bonne ou mauvaise, entraîne la suivante.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('orgueil', 'N''entrera pas au Paradis celui qui a dans son cœur le poids d''un atome d''orgueil. » Un homme dit : « On aime avoir de beaux vêtements et de belles chaussures. » Il dit : « Allah est Beau et Il aime la beauté. L''orgueil, c''est rejeter la vérité et mépriser les gens. »', null, 'Muslim n°91', 'Sahih', 'Rapporté par ''Abd Allah ibn Mas''ud. Il précise que l''orgueil n''est pas le soin de son apparence, mais le refus de la vérité et le mépris d''autrui.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('pas-envie', 'Ne vous enviez pas, ne faites pas monter les prix les uns contre les autres, ne vous haïssez pas, ne vous tournez pas le dos… Soyez, ô serviteurs d''Allah, des frères. Le musulman est le frère du musulman : il ne lui fait pas de tort, ne l''abandonne pas et ne le méprise pas… Il suffit comme mal pour une personne qu''elle méprise son frère musulman.', null, 'Muslim n°2564', 'Sahih', 'Rapporté par Abu Hurayra. C''est l''un des hadiths les plus complets sur la fraternité et les maladies du cœur.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('coeurs-actions', 'Allah ne regarde ni vos corps ni vos apparences, mais Il regarde vos cœurs et vos actions.', null, 'Muslim n°2564', 'Sahih', 'Rapporté par Abu Hurayra, dans le même hadith que le précédent. Il rappelle que la valeur véritable est intérieure.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('fort-colere', 'Le fort n''est pas celui qui terrasse les gens, mais le fort est celui qui se maîtrise lors de la colère.', null, 'Al-Bukhari n°6114 ; Muslim n°2609', 'Sahih', 'Rapporté par Abu Hurayra. Il redéfinit la force comme une maîtrise de soi.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('pas-colere', 'Un homme dit au Prophète ﷺ : « Conseille-moi. » Il dit : « Ne te mets pas en colère. » L''homme répéta plusieurs fois, et il lui répondait : « Ne te mets pas en colère. »', 'لَا تَغْضَبْ', 'Al-Bukhari n°6116', 'Sahih', 'Rapporté par Abu Hurayra. Les savants expliquent que la colère est la clé de nombreux maux ; s''en préserver protège de beaucoup de péchés.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('refuge-colere', 'Deux hommes se disputaient près du Prophète ﷺ ; l''un d''eux était rouge de colère. Le Prophète ﷺ dit : « Je connais une parole qui, s''il la disait, lui ôterait ce qu''il ressent : « Je cherche refuge auprès d''Allah contre Shaytan. »', null, 'Al-Bukhari n°6115 ; Muslim n°2610', 'Sahih', 'Rapporté par Sulayman ibn Surad. Un remède concret enseigné face à la colère.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('pudeur', 'La foi comporte soixante et quelques branches, et la pudeur (al-haya'') est une branche de la foi.', 'وَالْحَيَاءُ شُعْبَةٌ مِنَ الْإِيمَانِ', 'Al-Bukhari n°9 ; Muslim n°35', 'Sahih', 'Rapporté par Abu Hurayra. La pudeur est présentée comme un élément de la foi elle-même.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('pudeur-bien', 'La pudeur n''apporte que du bien.', null, 'Al-Bukhari n°6117 ; Muslim n°37', 'Sahih', 'Rapporté par ''Imran ibn Husayn.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('religion-ami', 'L''homme suit la religion de son ami intime ; que chacun de vous regarde donc qui il prend pour ami intime.', null, 'Abu Dawud n°4833 ; At-Tirmidhi n°2378', 'Hasan', 'Rapporté par Abu Hurayra. Il souligne l''influence profonde des fréquentations sur la pratique religieuse.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('musc-forgeron', 'Le bon et le mauvais compagnon sont comme le vendeur de musc et le forgeron : le vendeur de musc, soit il t''en offre, soit tu lui en achètes, soit tu sens auprès de lui une bonne odeur ; quant au forgeron, soit il brûle tes vêtements, soit tu sens auprès de lui une odeur désagréable.', null, 'Al-Bukhari n°2101 ; Muslim n°2628', 'Sahih', 'Rapporté par Abu Musa al-Ash''ari. Une parabole célèbre sur l''influence de l''entourage.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('deux-bienfaits', 'Il est deux bienfaits dont beaucoup de gens sont lésés : la santé et le temps libre.', null, 'Al-Bukhari n°6412', 'Sahih', 'Rapporté par Ibn ''Abbas. Il invite à ne pas gaspiller le temps, qui est un capital.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('delaisser-inutile', 'Fait partie du bon islam d''une personne le fait de délaisser ce qui ne la concerne pas.', null, 'At-Tirmidhi n°2317 ; Ibn Majah n°3976', 'Hasan (cité par an-Nawawi dans les 40 hadiths, n°12)', 'Rapporté par Abu Hurayra. Un principe essentiel face aux distractions et à la curiosité inutile.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('main-tendue', 'Allah tend Sa main la nuit pour que se repente celui qui a mal agi le jour, et Il tend Sa main le jour pour que se repente celui qui a mal agi la nuit, jusqu''à ce que le soleil se lève de son couchant.', null, 'Muslim n°2759', 'Sahih', 'Rapporté par Abu Musa al-Ash''ari. La porte du repentir reste ouverte à tout moment.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('joie-repentir', 'Allah se réjouit davantage du repentir de Son serviteur que l''un de vous qui retrouve sa monture après l''avoir perdue dans un désert.', null, 'Al-Bukhari n°6309 ; Muslim n°2747', 'Sahih', 'Rapporté par Anas ibn Malik. Il montre l''amour d''Allah pour celui qui revient vers Lui.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('soixante-dix', 'Par Allah, je demande pardon à Allah et je me repens à Lui plus de soixante-dix fois par jour.', null, 'Al-Bukhari n°6307', 'Sahih', 'Rapporté par Abu Hurayra. Le Prophète ﷺ, pourtant pardonné, montrait l''exemple d''un istighfar constant.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('agonie', 'Allah accepte le repentir du serviteur tant qu''il n''est pas à l''agonie.', null, 'At-Tirmidhi n°3537 ; Ibn Majah n°4253', 'Hasan', 'Rapporté par Ibn ''Umar. Il invite à ne pas reporter son repentir, car nul ne connaît l''heure de sa mort.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('regret', 'Le regret est un repentir.', 'النَّدَمُ تَوْبَةٌ', 'Ibn Majah n°4252 ; Ahmad n°3568', 'Sahih (authentifié par al-Albani)', 'Rapporté par ''Abd Allah ibn Mas''ud. Le regret sincère est le cœur même de la tawbah.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('comme-sans-peche', 'Celui qui se repent d''un péché est comme celui qui n''a pas de péché.', null, 'Ibn Majah n°4250', 'Hasan (selon al-Albani)', 'Rapporté par ''Abd Allah ibn Mas''ud. Un message d''espoir pour celui qui revient sincèrement.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('nuages-ciel', 'Allah le Très-Haut a dit : « Ô fils d''Adam ! Tant que tu M''invoques et que tu espères en Moi, Je te pardonne ce qui vient de toi, sans M''en soucier. Ô fils d''Adam ! Si tes péchés atteignaient les nuages du ciel, puis que tu Me demandais pardon, Je te pardonnerais… »', null, 'At-Tirmidhi n°3540', 'Hasan (selon at-Tirmidhi)', 'Hadith qudsi rapporté par Anas ibn Malik (n°42 des 40 hadiths d''an-Nawawi).', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('entoure-desirs', 'Le Paradis est entouré de choses désagréables, et l''Enfer est entouré de désirs.', null, 'Muslim n°2822 (et Al-Bukhari n°6487 avec « voilé »)', 'Sahih', 'Rapporté par Anas ibn Malik et Abu Hurayra. Le chemin du bien demande des efforts, tandis que le mal se présente souvent sous une forme attirante.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('crains-allah', 'Crains Allah où que tu sois, fais suivre la mauvaise action par une bonne qui l''effacera, et comporte-toi avec les gens d''un bon comportement.', null, 'At-Tirmidhi n°1987', 'Hasan', 'Conseil du Prophète ﷺ à Abu Dharr et Mu''adh ibn Jabal (n°18 des 40 hadiths d''an-Nawawi).', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('regularite', 'Les actions les plus aimées d''Allah sont les plus régulières, même si elles sont peu nombreuses.', null, 'Al-Bukhari n°6464 ; Muslim n°783', 'Sahih', 'Rapporté par ''A''icha. Un principe clé pour installer de bonnes habitudes durables.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('grands-peches', '« Voulez-vous que je vous informe du plus grand des grands péchés ? » … « Associer quelque chose à Allah et la désobéissance envers les parents. » Il était accoudé, puis il s''assit et dit : « Et la parole mensongère, et le faux témoignage. »', null, 'Al-Bukhari n°5976 ; Muslim n°87', 'Sahih', 'Rapporté par Abu Bakra. La désobéissance aux parents est citée juste après l''association.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('mere-trois', 'Un homme demanda : « Ô Messager d''Allah, qui a le plus droit à ma bonne compagnie ? » Il dit : « Ta mère. » — « Puis qui ? » — « Ta mère. » — « Puis qui ? » — « Ta mère. » — « Puis qui ? » — « Ton père. »', null, 'Al-Bukhari n°5971 ; Muslim n°2548', 'Sahih', 'Rapporté par Abu Hurayra.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('musulman-langue', 'Le musulman est celui dont les musulmans sont à l''abri de sa langue et de sa main.', null, 'Al-Bukhari n°10 ; Muslim n°40', 'Sahih', 'Rapporté par ''Abd Allah ibn ''Amr.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('sourire', 'Ne méprise aucune bonne action, ne serait-ce que de rencontrer ton frère avec un visage souriant.', null, 'Muslim n°2626', 'Sahih', 'Rapporté par Abu Dharr. Aucun bien n''est trop petit.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('abandon-priere', 'Entre l''homme et l''association et la mécréance, il y a l''abandon de la prière.', null, 'Muslim n°82', 'Sahih', 'Rapporté par Jabir ibn ''Abd Allah. Il montre la gravité de l''abandon de la prière ; les savants ont des avis détaillés sur le statut de celui qui la délaisse par négligence.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('riviere', '« Si une rivière coulait devant la porte de l''un de vous et qu''il s''y lavait cinq fois par jour, lui resterait-il de la saleté ? » Ils dirent : « Il ne lui en resterait rien. » Il dit : « Il en est de même des cinq prières : Allah efface par elles les péchés. »', null, 'Al-Bukhari n°528 ; Muslim n°667', 'Sahih', 'Rapporté par Abu Hurayra.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('priere-heure', '« Quelle est l''œuvre la plus aimée d''Allah ? » Il dit : « La prière accomplie à son heure. » — « Puis laquelle ? » — « La bonté envers les parents. » — « Puis laquelle ? » — « Le combat dans le sentier d''Allah. »', null, 'Al-Bukhari n°527 ; Muslim n°85', 'Sahih', 'Rapporté par ''Abd Allah ibn Mas''ud.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('vivant-mort', 'L''exemple de celui qui évoque son Seigneur et de celui qui ne L''évoque pas est comme l''exemple du vivant et du mort.', null, 'Al-Bukhari n°6407', 'Sahih', 'Rapporté par Abu Musa al-Ash''ari. Le dhikr est la vie du cœur.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('deux-paroles', 'Deux paroles légères sur la langue, lourdes dans la balance, aimées du Tout Miséricordieux : « Subhana Allahi wa bihamdihi, Subhana Allahi l-''Azim. »', null, 'Al-Bukhari n°6406 ; Muslim n°2694', 'Sahih', 'Rapporté par Abu Hurayra. C''est le dernier hadith du Sahih d''al-Bukhari.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('meilleur-coran', 'Le meilleur d''entre vous est celui qui apprend le Coran et l''enseigne.', null, 'Al-Bukhari n°5027', 'Sahih', 'Rapporté par ''Uthman ibn ''Affan.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('sadaqa-diminue', 'L''aumône ne diminue en rien les biens. Allah n''augmente le serviteur qui pardonne qu''en honneur, et nul ne s''humilie pour Allah sans qu''Allah ne l''élève.', null, 'Muslim n°2588', 'Sahih', 'Rapporté par Abu Hurayra. Il réunit la sadaqa, le pardon et l''humilité.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('sang-shaytan', 'Shaytan circule dans le fils d''Adam comme circule le sang.', null, 'Al-Bukhari n°2038 ; Muslim n°2175', 'Sahih', 'Rapporté par Safiyya. Le Prophète ﷺ l''a dit pour éviter que des gens aient de mauvaises pensées : il faut se méfier des suggestions de Shaytan.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('pense-pardonne', 'Allah a pardonné à ma communauté ce que leurs âmes se murmurent, tant qu''ils ne le mettent pas en acte ou ne le disent pas.', null, 'Al-Bukhari n°5269 ; Muslim n°127', 'Sahih', 'Rapporté par Abu Hurayra. Un réconfort pour ceux qui souffrent de waswas : les pensées non voulues ne sont pas comptées comme péchés.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('qui-a-cree', 'Shaytan vient à l''un de vous et dit : « Qui a créé ceci ? Qui a créé cela ? » jusqu''à dire : « Qui a créé ton Seigneur ? » Lorsqu''il en arrive là, qu''il cherche refuge auprès d''Allah et qu''il cesse.', null, 'Al-Bukhari n°3276 ; Muslim n°134', 'Sahih', 'Rapporté par Abu Hurayra. Le remède prophétique aux waswas : chercher refuge en Allah et ne pas s''y attarder.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('destructeur-plaisirs', 'Évoquez souvent le destructeur des plaisirs : la mort.', null, 'At-Tirmidhi n°2307 ; Ibn Majah n°4258', 'Hasan sahih (selon at-Tirmidhi)', 'Rapporté par Abu Hurayra. Se rappeler la mort aide à relativiser les plaisirs passagers.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('premiere-etape', 'La tombe est la première des étapes de l''au-delà : celui qui en est sauvé, ce qui vient après sera plus facile ; et celui qui n''en est pas sauvé, ce qui vient après sera plus dur.', null, 'At-Tirmidhi n°2308 ; Ibn Majah n°4267', 'Hasan', 'Rapporté par ''Uthman ibn ''Affan, qui pleurait lorsqu''il se tenait devant une tombe.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('pieds-bougeront', 'Les pieds du serviteur ne bougeront pas le Jour de la Résurrection avant qu''il ne soit interrogé sur sa vie et ce qu''il en a fait, sur sa science et ce qu''il en a fait, sur ses biens — d''où il les a acquis et comment il les a dépensés — et sur son corps et ce qu''il en a usé.', null, 'At-Tirmidhi n°2417', 'Hasan sahih (selon at-Tirmidhi)', 'Rapporté par Abu Barza al-Aslami. Il résume la responsabilité de chaque personne devant Allah.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('cent-parts', 'Allah a fait la miséricorde en cent parts. Il en a gardé auprès de Lui quatre-vingt-dix-neuf et en a fait descendre sur terre une seule part. C''est par cette part que les créatures se font miséricorde…', null, 'Al-Bukhari n°6000 ; Muslim n°2752', 'Sahih', 'Rapporté par Abu Hurayra. Il donne une idée de l''immensité de la miséricorde divine.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('misericorde-devance', 'Lorsqu''Allah créa la création, Il écrivit dans un Livre qui est auprès de Lui, au-dessus du Trône : « Ma miséricorde devance Ma colère. »', null, 'Al-Bukhari n°7404 ; Muslim n°2751', 'Sahih', 'Rapporté par Abu Hurayra.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('jeunes-mariage', 'Ô assemblée de jeunes gens ! Que celui d''entre vous qui en a les moyens se marie, car cela aide davantage à baisser le regard et à préserver la chasteté. Et celui qui ne le peut pas, qu''il jeûne, car ce sera pour lui une protection.', null, 'Al-Bukhari n°5066 ; Muslim n°1400', 'Sahih', 'Rapporté par ''Abd Allah ibn Mas''ud. Une solution prophétique concrète face au désir.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('troisieme-shaytan', 'Un homme ne s''isole pas avec une femme sans que Shaytan ne soit leur troisième.', null, 'At-Tirmidhi n°2165', 'Sahih (selon at-Tirmidhi : hasan sahih gharib)', 'Rapporté par ''Umar ibn al-Khattab. Il interdit l''isolement (khalwa) entre un homme et une femme qui ne sont pas mahram.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('fitna-femmes', 'Je n''ai pas laissé après moi d''épreuve plus nuisible pour les hommes que les femmes.', null, 'Al-Bukhari n°5096 ; Muslim n°2740', 'Sahih', 'Rapporté par Usama ibn Zayd. Les savants expliquent qu''il s''agit d''un avertissement sur la force de l''attirance et non d''un mépris envers les femmes ; l''islam honore la femme et appelle les deux sexes à la pudeur.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('vetues-nues', 'Il y a deux catégories parmi les gens du Feu que je n''ai pas vues : … des femmes vêtues mais nues, qui se pavanent et attirent [les regards]… Elles n''entreront pas au Paradis et n''en sentiront pas le parfum…', null, 'Muslim n°2128', 'Sahih', 'Rapporté par Abu Hurayra. Les savants expliquent « vêtues mais nues » par des vêtements transparents, moulants ou qui découvrent. C''est un avertissement général sur un comportement, non un jugement sur une personne précise.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('or-soie', 'La soie et l''or ont été rendus licites pour les femmes de ma communauté et interdits pour ses hommes.', null, 'At-Tirmidhi n°1720 ; An-Nasa''i n°5148', 'Sahih', 'Rapporté par Abu Musa al-Ash''ari. Une des prescriptions vestimentaires propres aux hommes.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('etranger-voyageur', 'Sois dans ce monde comme si tu étais un étranger ou un voyageur de passage.', null, 'Al-Bukhari n°6416', 'Sahih', 'Conseil du Prophète ﷺ à ''Abd Allah ibn ''Umar.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('deux-vallees', 'Si le fils d''Adam possédait deux vallées d''or, il en voudrait une troisième. Rien ne remplit le ventre du fils d''Adam si ce n''est la terre [de la tombe]. Et Allah accepte le repentir de celui qui se repent.', null, 'Al-Bukhari n°6436 ; Muslim n°1048', 'Sahih', 'Rapporté par Ibn ''Abbas et Anas. Sur l''avidité et l''attachement au bas monde.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('laisse-pour-allah', 'Tu ne laisseras jamais une chose par crainte d''Allah sans qu''Allah ne te donne mieux qu''elle.', null, 'Musnad Ahmad (5/363)', 'Sahih (selon Shu''ayb al-Arna''ut et al-Albani)', 'Rapporté par un compagnon bédouin. Un grand encouragement pour celui qui abandonne une habitude interdite.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('cinq-avant-cinq', 'Profite de cinq choses avant cinq autres : ta jeunesse avant ta vieillesse, ta santé avant ta maladie, ta richesse avant ta pauvreté, ton temps libre avant tes occupations, et ta vie avant ta mort.', null, 'Al-Hakim, Al-Mustadrak n°7846', 'Sahih (authentifié par al-Albani)', 'Rapporté par Ibn ''Abbas. Un remède à la procrastination religieuse.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('remercier-gens', 'Celui qui ne remercie pas les gens ne remercie pas Allah.', null, 'Abu Dawud n°4811 ; At-Tirmidhi n°1954', 'Sahih', 'Rapporté par Abu Hurayra.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('croyant-etonnant', 'Étonnante est l''affaire du croyant ! Tout ce qui lui arrive est un bien pour lui, et cela n''est donné qu''au croyant : s''il lui arrive une chose heureuse, il remercie, et c''est un bien pour lui ; s''il lui arrive un malheur, il patiente, et c''est un bien pour lui.', null, 'Muslim n°2999', 'Sahih', 'Rapporté par Suhayb. Il réunit la gratitude et la patience.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('injustice', 'L''injustice sera des ténèbres le Jour de la Résurrection.', null, 'Al-Bukhari n°2447 ; Muslim n°2579', 'Sahih', 'Rapporté par ''Abd Allah ibn ''Umar.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('hypocrite', 'Les signes de l''hypocrite sont trois : lorsqu''il parle, il ment ; lorsqu''il promet, il ne tient pas sa promesse ; et lorsqu''on lui confie quelque chose, il trahit.', null, 'Al-Bukhari n°33 ; Muslim n°59', 'Sahih', 'Rapporté par Abu Hurayra. Les savants précisent qu''il s''agit de traits de comportement hypocrite dont le croyant doit se préserver.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('insulte', 'Insulter le musulman est une perversité, et le combattre est de la mécréance.', null, 'Al-Bukhari n°48 ; Muslim n°64', 'Sahih', 'Rapporté par ''Abd Allah ibn Mas''ud.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('pas-croyant-grossier', 'Le croyant n''est pas celui qui dénigre, qui maudit, qui est grossier ou obscène.', null, 'At-Tirmidhi n°1977', 'Hasan', 'Rapporté par ''Abd Allah ibn Mas''ud.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('ostentation', 'Ce que je crains le plus pour vous, c''est le petit shirk. » On demanda : « Qu''est-ce que le petit shirk ? » Il dit : « L''ostentation (ar-riya''). »', null, 'Ahmad n°23630', 'Hasan / sahih selon plusieurs savants (dont al-Albani)', 'Rapporté par Mahmud ibn Labid. Il concerne le fait d''agir pour être vu et admiré des gens — un danger accru à l''ère des réseaux sociaux.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('aimer-frere', 'Aucun de vous n''est [vraiment] croyant tant qu''il n''aime pas pour son frère ce qu''il aime pour lui-même.', null, 'Al-Bukhari n°13 ; Muslim n°45', 'Sahih', 'Rapporté par Anas ibn Malik. Le remède direct à la jalousie.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('garantie-paradis', 'Celui qui me garantit [la préservation de] ce qui est entre ses deux mâchoires et ce qui est entre ses deux jambes, je lui garantis le Paradis.', null, 'Al-Bukhari n°6474', 'Sahih', 'Rapporté par Sahl ibn Sa''d. La langue et la chasteté : deux portes majeures.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('balance-caractere', 'Rien n''est plus lourd dans la balance du croyant, le Jour de la Résurrection, qu''un bon caractère.', null, 'At-Tirmidhi n°2002 ; Abu Dawud n°4799', 'Sahih', 'Rapporté par Abu ad-Darda''.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('peches-meprises', 'Prenez garde aux péchés que l''on considère comme insignifiants, car ils s''accumulent sur l''homme jusqu''à le détruire.', null, 'Ahmad n°3818', 'Sahih (selon al-Albani, Sahih al-Jami'' n°2686)', 'Rapporté par ''Abd Allah ibn Mas''ud. Le Prophète ﷺ l''a illustré par des gens qui ramassent chacun un petit bâton jusqu''à pouvoir allumer un grand feu.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('plus-fin-cheveu', 'Vous commettez des actes qui sont à vos yeux plus fins qu''un cheveu, alors que nous les comptions, à l''époque du Prophète ﷺ, parmi les choses qui mènent à la perdition.', null, 'Al-Bukhari n°6492', 'Sahih (parole du compagnon Anas ibn Malik)', 'Il s''agit d''une parole d''Anas ibn Malik adressée à la génération suivante, et non d''une parole du Prophète ﷺ. Elle décrit exactement le phénomène de banalisation.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('montagne', 'Le croyant voit ses péchés comme s''il était assis au pied d''une montagne dont il craint qu''elle ne tombe sur lui, tandis que le pervers voit ses péchés comme une mouche passée sur son nez, qu''il chasse ainsi [d''un geste].', null, 'Al-Bukhari n°6308', 'Sahih (parole du compagnon Ibn Mas''ud)', 'Parole de ''Abd Allah ibn Mas''ud rapportée par al-Bukhari, dans le chapitre du repentir.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('mujahirin', 'Toute ma communauté sera pardonnée, sauf ceux qui exposent publiquement [leurs péchés]. Fait partie de cela qu''un homme commette un acte la nuit, puis, alors qu''Allah l''a couvert, il dit au matin : « Ô untel, j''ai fait hier ceci et cela. »', null, 'Al-Bukhari n°6069 ; Muslim n°2990', 'Sahih', 'Rapporté par Abu Hurayra. Très actuel à l''ère des stories et publications : ne pas exposer ses péchés.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('peche-trouble', 'La piété est le bon caractère, et le péché est ce qui trouble ton âme et que tu détestes que les gens découvrent.', null, 'Muslim n°2553', 'Sahih', 'Rapporté par an-Nawwas ibn Sam''an. Un critère intérieur pour reconnaître le péché.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('laisse-doute', 'Laisse ce qui te fait douter pour ce qui ne te fait pas douter.', null, 'At-Tirmidhi n°2518 ; An-Nasa''i n°5711', 'Sahih', 'Rapporté par al-Hasan ibn ''Ali (n°11 des 40 hadiths d''an-Nawawi).', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('rapprocher-nawafil', 'Allah a dit : « …Mon serviteur ne cesse de se rapprocher de Moi par les œuvres surérogatoires jusqu''à ce que Je l''aime… »', null, 'Al-Bukhari n°6502', 'Sahih', 'Hadith qudsi rapporté par Abu Hurayra. Le chemin de l''amour d''Allah passe par les obligations puis les actes surérogatoires.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('tasbih-priere', 'Celui qui, après chaque prière, glorifie Allah 33 fois (Subhan Allah), Le loue 33 fois (Al-hamdu lillah) et proclame Sa grandeur 33 fois (Allahu akbar) — cela fait 99 — puis complète la centaine par : « La ilaha illa Allah wahdahu la sharika lah, lahu l-mulku wa lahu l-hamd, wa huwa ''ala kulli shay''in qadir », ses péchés lui sont pardonnés, fussent-ils comme l''écume de la mer.', null, 'Muslim n°597', 'Sahih', 'Rapporté par Abu Hurayra.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('meilleur-dhikr', 'Le meilleur rappel est « La ilaha illa Allah », et la meilleure invocation est « Al-hamdu lillah ».', null, 'At-Tirmidhi n°3383 ; Ibn Majah n°3800', 'Hasan', 'Rapporté par Jabir ibn ''Abd Allah.', 'review') on conflict (id) do nothing;
insert into public.hadiths (id, texte_fr, texte_ar, reference, grade, contexte, status) values ('sayyid-istighfar', 'Le maître des demandes de pardon (Sayyid al-istighfar) est que tu dises : « Allahumma anta rabbi… ». Celui qui la dit le jour avec conviction et meurt ce jour-là avant le soir fait partie des gens du Paradis, et celui qui la dit la nuit avec conviction et meurt avant le matin fait partie des gens du Paradis.', null, 'Al-Bukhari n°6306', 'Sahih', 'Rapporté par Shaddad ibn Aws.', 'review') on conflict (id) do nothing;
insert into public.invocations (id, titre, theme, texte_ar, translitteration, traduction_fr, reference, status) values ('sayyid-istighfar', 'Sayyid al-istighfar (le maître du repentir)', 'Repentir', 'اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ لَكَ بِذَنْبِي، فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ', 'Allāhumma anta rabbī, lā ilāha illā anta, khalaqtanī wa anā ʿabduka, wa anā ʿalā ʿahdika wa waʿdika mā staṭaʿtu, aʿūdhu bika min sharri mā ṣanaʿtu, abū''u laka bi-niʿmatika ʿalayya, wa abū''u laka bi-dhanbī, fa-ghfir lī fa-innahu lā yaghfiru dh-dhunūba illā anta.', 'Ô Allah, Tu es mon Seigneur, il n''y a de divinité que Toi. Tu m''as créé et je suis Ton serviteur. Je respecte mon engagement et ma promesse envers Toi autant que je le peux. Je cherche refuge auprès de Toi contre le mal que j''ai commis. Je reconnais Tes bienfaits envers moi et je reconnais mon péché. Pardonne-moi donc, car nul ne pardonne les péchés en dehors de Toi.', 'Al-Bukhari n°6306', 'review') on conflict (id) do nothing;
insert into public.invocations (id, titre, theme, texte_ar, translitteration, traduction_fr, reference, status) values ('astaghfirullah', 'Demander pardon', 'Repentir', 'أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ', 'Astaghfiru Llāha wa atūbu ilayh.', 'Je demande pardon à Allah et je me repens à Lui.', 'Al-Bukhari n°6307 (formule employée par le Prophète ﷺ)', 'review') on conflict (id) do nothing;
insert into public.invocations (id, titre, theme, texte_ar, translitteration, traduction_fr, reference, status) values ('adam', 'L''invocation d''Adam et Hawwa', 'Repentir', 'رَبَّنَا ظَلَمْنَا أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ', 'Rabbanā ẓalamnā anfusanā wa in lam taghfir lanā wa tarḥamnā la-nakūnanna mina l-khāsirīn.', 'Notre Seigneur, nous avons fait du tort à nous-mêmes. Si Tu ne nous pardonnes pas et ne nous fais pas miséricorde, nous serons très certainement du nombre des perdants.', 'Coran, Al-A''raf 7:23', 'review') on conflict (id) do nothing;
insert into public.invocations (id, titre, theme, texte_ar, translitteration, traduction_fr, reference, status) values ('yunus', 'L''invocation de Yunus (Jonas)', 'Détresse', 'لَا إِلَٰهَ إِلَّا أَنتَ سُبْحَانَكَ إِنِّي كُنتُ مِنَ الظَّالِمِينَ', 'Lā ilāha illā anta, subḥānaka, innī kuntu mina ẓ-ẓālimīn.', 'Pas de divinité à part Toi ! Gloire à Toi ! J''ai été vraiment du nombre des injustes.', 'Coran, Al-Anbiya'' 21:87 ; voir aussi At-Tirmidhi n°3505', 'review') on conflict (id) do nothing;
insert into public.invocations (id, titre, theme, texte_ar, translitteration, traduction_fr, reference, status) values ('coeur-ferme', 'Pour la fermeté du cœur', 'Cœur', 'يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ', 'Yā muqalliba l-qulūb, thabbit qalbī ʿalā dīnik.', 'Ô Toi qui retournes les cœurs, affermis mon cœur sur Ta religion.', 'At-Tirmidhi n°2140 (hasan)', 'review') on conflict (id) do nothing;
insert into public.invocations (id, titre, theme, texte_ar, translitteration, traduction_fr, reference, status) values ('ne-pas-devier', 'Pour ne pas dévier après la guidée', 'Cœur', 'رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ الْوَهَّابُ', 'Rabbanā lā tuzigh qulūbanā baʿda idh hadaytanā wa hab lanā min ladunka raḥmah, innaka anta l-wahhāb.', 'Seigneur, ne laisse pas dévier nos cœurs après que Tu nous as guidés, et accorde-nous Ta miséricorde. C''est Toi le Grand Donateur.', 'Coran, Al ''Imran 3:8', 'review') on conflict (id) do nothing;
insert into public.invocations (id, titre, theme, texte_ar, translitteration, traduction_fr, reference, status) values ('huda-afaf', 'Guidée, piété et chasteté', 'Chasteté', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى', 'Allāhumma innī as''aluka l-hudā wa t-tuqā wa l-ʿafāfa wa l-ghinā.', 'Ô Allah, je Te demande la guidée, la piété, la chasteté et la suffisance.', 'Muslim n°2721', 'review') on conflict (id) do nothing;
insert into public.invocations (id, titre, theme, texte_ar, translitteration, traduction_fr, reference, status) values ('sens', 'Protection du regard, de la langue et du cœur', 'Chasteté', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ سَمْعِي، وَمِنْ شَرِّ بَصَرِي، وَمِنْ شَرِّ لِسَانِي، وَمِنْ شَرِّ قَلْبِي، وَمِنْ شَرِّ مَنِيِّي', 'Allāhumma innī aʿūdhu bika min sharri samʿī, wa min sharri baṣarī, wa min sharri lisānī, wa min sharri qalbī, wa min sharri maniyyī.', 'Ô Allah, je cherche refuge auprès de Toi contre le mal de mon ouïe, le mal de ma vue, le mal de ma langue, le mal de mon cœur et le mal de mon désir.', 'Abu Dawud n°1551 ; At-Tirmidhi n°3492 (sahih)', 'review') on conflict (id) do nothing;
insert into public.invocations (id, titre, theme, texte_ar, translitteration, traduction_fr, reference, status) values ('akhlaq', 'Pour un bon caractère', 'Comportement', 'اللَّهُمَّ اهْدِنِي لِأَحْسَنِ الْأَخْلَاقِ لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ، وَاصْرِفْ عَنِّي سَيِّئَهَا لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلَّا أَنْتَ', 'Allāhumma hdinī li-aḥsani l-akhlāq, lā yahdī li-aḥsanihā illā anta, wa ṣrif ʿannī sayyi''ahā, lā yaṣrifu ʿannī sayyi''ahā illā anta.', 'Ô Allah, guide-moi vers le meilleur comportement, nul ne guide vers le meilleur sinon Toi ; et écarte de moi le mauvais comportement, nul ne l''écarte de moi sinon Toi.', 'Muslim n°771', 'review') on conflict (id) do nothing;
insert into public.invocations (id, titre, theme, texte_ar, translitteration, traduction_fr, reference, status) values ('dhikr-shukr', 'Pour le rappel et la gratitude', 'Dhikr', 'اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ', 'Allāhumma aʿinnī ʿalā dhikrika wa shukrika wa ḥusni ʿibādatik.', 'Ô Allah, aide-moi à T''évoquer, à Te remercier et à bien T''adorer.', 'Abu Dawud n°1522 ; An-Nasa''i n°1303 (sahih)', 'review') on conflict (id) do nothing;
insert into public.invocations (id, titre, theme, texte_ar, translitteration, traduction_fr, reference, status) values ('hamm', 'Contre l''anxiété et la paresse', 'Détresse', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ، وَغَلَبَةِ الرِّجَالِ', 'Allāhumma innī aʿūdhu bika mina l-hammi wa l-ḥazan, wa l-ʿajzi wa l-kasal, wa l-bukhli wa l-jubn, wa ḍalaʿi d-dayn, wa ghalabati r-rijāl.', 'Ô Allah, je cherche refuge auprès de Toi contre le souci et la tristesse, l''incapacité et la paresse, l''avarice et la lâcheté, le poids des dettes et la domination des hommes.', 'Al-Bukhari n°6369', 'review') on conflict (id) do nothing;
insert into public.invocations (id, titre, theme, texte_ar, translitteration, traduction_fr, reference, status) values ('taawudh', 'Chercher refuge contre Shaytan', 'Protection', 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ', 'Aʿūdhu bi-Llāhi mina sh-shayṭāni r-rajīm.', 'Je cherche refuge auprès d''Allah contre Shaytan le maudit.', 'Coran, An-Nahl 16:98 ; Al-Bukhari n°6115 (face à la colère)', 'review') on conflict (id) do nothing;
insert into public.invocations (id, titre, theme, texte_ar, translitteration, traduction_fr, reference, status) values ('kaffara-majlis', 'Expiation d''une assemblée', 'Langue', 'سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ', 'Subḥānaka Llāhumma wa bi-ḥamdik, ash-hadu an lā ilāha illā anta, astaghfiruka wa atūbu ilayk.', 'Gloire et louange à Toi, ô Allah. J''atteste qu''il n''y a de divinité que Toi. Je Te demande pardon et je me repens à Toi.', 'At-Tirmidhi n°3433 (sahih)', 'review') on conflict (id) do nothing;
insert into public.invocations (id, titre, theme, texte_ar, translitteration, traduction_fr, reference, status) values ('sans-rancoeur', 'Pour un cœur sans rancœur', 'Cœur', 'رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلًّا لِّلَّذِينَ آمَنُوا رَبَّنَا إِنَّكَ رَءُوفٌ رَّحِيمٌ', 'Rabbanā ghfir lanā wa li-ikhwāninā lladhīna sabaqūnā bi-l-īmān, wa lā tajʿal fī qulūbinā ghillan li-lladhīna āmanū, rabbanā innaka ra''ūfun raḥīm.', 'Seigneur, pardonne-nous ainsi qu''à nos frères qui nous ont précédés dans la foi, et ne mets dans nos cœurs aucune rancœur envers ceux qui ont cru. Seigneur, Tu es Compatissant et Très Miséricordieux.', 'Coran, Al-Hashr 59:10', 'review') on conflict (id) do nothing;
insert into public.invocations (id, titre, theme, texte_ar, translitteration, traduction_fr, reference, status) values ('parents', 'Pour les parents', 'Famille', 'رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا', 'Rabbi rḥamhumā kamā rabbayānī ṣaghīrā.', 'Seigneur, fais-leur miséricorde comme ils m''ont élevé tout petit.', 'Coran, Al-Isra 17:24', 'review') on conflict (id) do nothing;
insert into public.invocations (id, titre, theme, texte_ar, translitteration, traduction_fr, reference, status) values ('famille', 'Pour sa famille', 'Famille', 'رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا', 'Rabbanā hab lanā min azwājinā wa dhurriyyātinā qurrata aʿyun, wa jʿalnā li-l-muttaqīna imāmā.', 'Seigneur, donne-nous, en nos épouses et nos descendants, la joie des yeux, et fais de nous un guide pour les pieux.', 'Coran, Al-Furqan 25:74', 'review') on conflict (id) do nothing;
insert into public.invocations (id, titre, theme, texte_ar, translitteration, traduction_fr, reference, status) values ('dunya-akhira', 'Le bien ici-bas et dans l''au-delà', 'Général', 'رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ', 'Rabbanā ātinā fi d-dunyā ḥasanatan wa fi l-ākhirati ḥasanatan wa qinā ʿadhāba n-nār.', 'Seigneur, accorde-nous une belle part ici-bas et une belle part dans l''au-delà, et protège-nous du châtiment du Feu.', 'Coran, Al-Baqara 2:201 ; invocation fréquente du Prophète ﷺ (Al-Bukhari n°6389)', 'review') on conflict (id) do nothing;
insert into public.invocations (id, titre, theme, texte_ar, translitteration, traduction_fr, reference, status) values ('hasbuna', 'La confiance en Allah', 'Détresse', 'حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ', 'Ḥasbunā Llāhu wa niʿma l-wakīl.', 'Allah nous suffit ; Il est notre meilleur garant.', 'Coran, Al ''Imran 3:173 ; Al-Bukhari n°4563', 'review') on conflict (id) do nothing;
insert into public.invocations (id, titre, theme, texte_ar, translitteration, traduction_fr, reference, status) values ('deux-paroles', 'Deux paroles lourdes dans la balance', 'Dhikr', 'سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ', 'Subḥāna Llāhi wa bi-ḥamdih, subḥāna Llāhi l-ʿaẓīm.', 'Gloire et louange à Allah, gloire à Allah l''Immense.', 'Al-Bukhari n°6406 ; Muslim n°2694', 'review') on conflict (id) do nothing;
insert into public.invocations (id, titre, theme, texte_ar, translitteration, traduction_fr, reference, status) values ('tawakkul-sortie', 'En sortant de chez soi', 'Protection', 'بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ', 'Bismi Llāh, tawakkaltu ʿala Llāh, wa lā ḥawla wa lā quwwata illā bi-Llāh.', 'Au nom d''Allah, je place ma confiance en Allah ; il n''y a de force ni de puissance qu''en Allah.', 'Abu Dawud n°5095 ; At-Tirmidhi n°3426', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('pornographie', 'regard', 'La pornographie', 'Quelques clics « en privé »… et une chaîne invisible autour du cœur.', 'Interdit (haram) — unanimité des savants', 'Elle se consomme seul, en silence, souvent la nuit. Beaucoup se disent « ce n''est pas grave, je ne fais de mal à personne ». Pourtant, chaque visionnage laisse une trace dans le cœur, l''esprit et la relation avec Allah.', 'La pornographie regroupe toutes les images et vidéos à caractère sexuel explicite. Elle réunit plusieurs interdits : le regard illicite, la recherche volontaire du désir interdit et, souvent, la consommation de contenus produits dans l''exploitation de personnes.', 'Elle attaque directement ce que le Coran ordonne de préserver : le regard et la chasteté. Elle crée une dépendance réelle, banalise l''interdit, altère la vision du mariage et éteint progressivement la douceur de la foi.', 'Allah n''a pas seulement interdit la fornication : Il a interdit de s''en approcher (17:32). Le regard est la première étape de ce chemin. Le hadith de la « zina des yeux » montre que l''islam protège la chasteté dès sa porte d''entrée. Et chaque regard est enregistré : « l''ouïe, la vue et le cœur, sur tout cela on sera interrogé ».', 'Souvent par une curiosité d''adolescent, une image croisée sur les réseaux, l''ennui ou la solitude. Puis vient l''habitude : le cerveau associe stress, fatigue ou tristesse à ce « soulagement ». Le téléphone dans le lit et l''absence de cadre font le reste.', array['Le cœur s''endurcit et la prière perd sa saveur.','Sentiment de honte et de double vie qui pousse à s''isoler.','Dépendance : besoin de contenus toujours plus extrêmes.','Vision déformée de l''intimité et difficultés dans le mariage.','Perte de temps, de concentration et d''énergie.']::text[], array['Tu y penses dès que tu es seul avec ton téléphone.','Tu as essayé d''arrêter plusieurs fois sans y parvenir.','Tu effaces ton historique par réflexe.','Tu te sens vide ou honteux juste après.']::text[], array['Reconnaître le problème sans se mépriser : c''est un combat, pas une identité.','Supprimer les accès : bloqueurs de contenus, filtre DNS, suppression des comptes et applications déclencheurs.','Ne jamais garder le téléphone dans la chambre la nuit.','Identifier ses moments à risque (fatigue, solitude, ennui) et préparer une alternative.','Remplacer : sport, sortie, appel à un ami, ablutions et deux rakats.','Jeûner, comme l''a conseillé le Prophète ﷺ aux jeunes (Bukhari 5066).','Se confier à une personne de confiance ou à un professionnel si la dépendance est forte.']::text[], array['Jour 1 : installer un bloqueur et supprimer les applications déclencheurs.','Jour 2 : sortir le téléphone de la chambre la nuit.','Jour 3 : noter tes trois moments à risque et une alternative pour chacun.','Jour 4 : prier à l''heure les cinq prières et faire le dhikr du matin et du soir.','Jour 5 : jeûner (un jour surérogatoire, lundi ou jeudi par exemple).','Jour 6 : faire du sport ou une activité physique de 30 minutes.','Jour 7 : faire le bilan, renouveler ta tawbah et continuer.']::text[], array['nur-30','isra-32','isra-36']::text[], array['zina-yeux','regard-ali','garantie-paradis']::text[], 'sens', 'Allah connaît ton combat silencieux et Il aime celui qui revient vers Lui. Chaque fois que tu détournes le regard pour Lui, tu gagnes. Chaque rechute n''est pas une fin, mais un appel à revenir encore. Tu n''es pas seul : des milliers de croyants ont gagné ce combat avec la permission d''Allah.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('pornographie', 'regard', 'La pornographie', 'Interdit (haram) — unanimité des savants', 'pornographie', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('regard-desir', 'regard', 'Regarder les gens avec désir', '« Ce n''est qu''un regard »… vraiment ?', 'Interdit (haram) lorsque le regard est volontaire et chargé de désir', 'Dans la rue, au travail, à l''école : on regarde, on fixe, on se retourne. Beaucoup ne considèrent même plus cela comme un péché.', 'Il s''agit de regarder volontairement, avec insistance ou avec désir, une personne qui ne nous est pas permise. Le premier regard involontaire n''est pas reproché ; c''est le fait de le prolonger ou de le répéter qui l''est.', 'Le regard est le messager du cœur : il nourrit le désir, la comparaison, l''insatisfaction et ouvre la porte à des actes plus graves.', 'L''ordre de baisser le regard concerne autant les hommes (24:30) que les femmes (24:31). Il ne s''agit pas de marcher les yeux fermés, mais de ne pas laisser le regard se poser volontairement là où il n''a pas le droit d''aller.', 'Par la répétition : plus on se permet de regarder, moins on ressent de gêne. L''environnement (publicités, réseaux, tenues) rend le regard « normal ».', array['Le cœur se disperse et se remplit de désirs.','La comparaison abîme la satisfaction dans le mariage.','La lumière de la foi faiblit.','Le regard prépare les étapes suivantes (paroles, rencontres…).']::text[], array['Tu te retournes sur les gens.','Tu fixes des parties du corps.','Tu cherches à recroiser une personne qui t''attire.']::text[], array['Appliquer la règle du « premier regard » : détourner immédiatement.','Marcher avec un objectif et regarder devant soi.','Faire du dhikr à voix basse dans la rue.','Limiter les lieux et contenus qui exposent inutilement.']::text[], array['Choisir une formule de dhikr à répéter dans la rue.','Repérer tes lieux à risque et adapter ton trajet si possible.','Chaque soir, faire un istighfar pour les regards de la journée.','Te récompenser (sans péché) après une semaine d''efforts.']::text[], array['nur-30','nur-31']::text[], array['regard-ali','zina-yeux']::text[], 'sens', 'Baisser le regard est une adoration discrète que seul Allah voit. Il est « plus pur » pour toi (24:30) : ton cœur s''allège à chaque fois que tu choisis Allah plutôt qu''un instant de plaisir.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('regard-desir', 'regard', 'Regarder les gens avec désir', 'Interdit (haram) lorsque le regard est volontaire et chargé de désir', 'regard-desir', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('images-indecentes', 'regard', 'Les images indécentes', 'Elles défilent sous tes yeux sans que tu les cherches… et pourtant tu restes.', 'Regarder volontairement est interdit', 'Publicités, clips, séries, affiches : les images dénudées sont partout. Le danger n''est pas seulement de les croiser, mais de s''y arrêter et de s''y habituer.', 'Ce sont les photos, vidéos ou illustrations qui exposent la nudité ou mettent en avant le corps de manière provocante.', 'À force d''exposition, le cœur ne ressent plus de gêne ; ce qui était choquant devient banal. C''est exactement ce que décrit le verset : « vous le considériez insignifiant alors qu''auprès d''Allah c''était énorme ».', 'L''islam ne demande pas d''éviter ce qu''on ne peut pas empêcher, mais de ne pas s''y attarder et de réduire volontairement son exposition.', 'Par l''algorithme : chaque arrêt sur une image en propose davantage. Par la culture du divertissement où l''indécence est la norme.', array['Désensibilisation : on ne voit plus le mal.','Désirs et pensées envahissantes.','Préparation à des contenus plus graves.']::text[], array['Tu ne remarques plus le caractère indécent de ce que tu regardes.','Tu laisses tourner un clip ou une série malgré les scènes.']::text[], array['Passer, fermer, ne pas « liker » : l''algorithme apprend de tes réactions.','Choisir des contenus propres et bénéfiques.','Signaler et masquer les contenus indécents.']::text[], array['Nettoyer tes abonnements (cinq comptes aujourd''hui).','Utiliser les options « pas intéressé ».','Remplacer une série par un programme bénéfique.']::text[], array['nur-30','nur-15','isra-36']::text[], array['zina-yeux','peches-meprises']::text[], 'sens', 'Ton regard est un dépôt confié par Allah. Chaque image que tu refuses est un acte de fidélité envers Lui, et Il te remplacera par mieux.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('images-indecentes', 'regard', 'Les images indécentes', 'Regarder volontairement est interdit', 'images-indecentes', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('videos-sexuelles', 'regard', 'Les vidéos sexuelles', 'Partagées dans les groupes, envoyées « pour rire »… elles ne sont jamais anodines.', 'Interdit (haram) — regarder, partager et diffuser', 'Au-delà des sites spécialisés, les vidéos sexuelles circulent dans les groupes de discussion, les messageries et les réseaux, parfois sans consentement des personnes filmées.', 'Regarder, conserver, transmettre ou commenter de telles vidéos multiplie le péché : on le commet soi-même et on le propage chez les autres.', 'Celui qui diffuse participe à la propagation de la turpitude parmi les croyants, ce que le Coran condamne sévèrement. Et ce qui est partagé peut continuer à circuler longtemps.', 'Le verset 24:19 vise même ceux qui « aiment » que la turpitude se répande. Transférer une vidéo, c''est s''en rendre complice.', 'Par effet de groupe : « tout le monde regarde », « c''est juste une blague ». Par la peur de passer pour coincé.', array['Péché multiplié par chaque partage.','Atteinte à l''honneur de personnes réelles (et risques pénaux dans de nombreux pays).','Banalisation dans le groupe d''amis.']::text[], array['Tu reçois et ouvres ce type de contenu dans des groupes.','Tu as déjà transféré une vidéo « pour rire ».']::text[], array['Supprimer immédiatement, ne jamais transférer.','Quitter ou mettre en sourdine les groupes qui en partagent.','Dire clairement et poliment que tu ne veux pas recevoir ce genre de contenu.']::text[], array['Supprimer les contenus stockés aujourd''hui.','Désactiver le téléchargement automatique des médias.','Quitter un groupe problématique.']::text[], array['nur-19','nur-30']::text[], array['mujahirin','zina-yeux']::text[], 'huda-afaf', 'En refusant de partager, tu protèges ton cœur et celui des autres. Celui qui devient une barrière au mal reçoit la récompense du bien qu''il préserve.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('videos-sexuelles', 'regard', 'Les vidéos sexuelles', 'Interdit (haram) — regarder, partager et diffuser', 'videos-sexuelles', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('comptes-provocateurs', 'regard', 'Suivre des comptes provocateurs', 'Un abonnement, c''est une invitation quotidienne dans ton téléphone.', 'Interdit lorsque le contenu suivi expose à ce qui est illicite', 'Influenceurs dénudés, comptes « fitness » ambigus, pages de danse suggestive : on s''abonne « par curiosité » et on les retrouve chaque jour.', 'Suivre un compte, c''est choisir de recevoir régulièrement son contenu. Lorsque ce contenu repose sur le corps et la provocation, l''abonnement devient une exposition volontaire et quotidienne.', 'C''est une exposition programmée au regard illicite, et un soutien (vues, likes) à la diffusion de l''indécence.', 'Le principe du hadith « délaisser ce qui ne te concerne pas » s''applique parfaitement : ce compte n''apporte rien à ta vie, ni dans ce monde ni dans l''autre.', 'Par les suggestions de l''application, les « reels » et l''envie de voir « ce qui se passe ».', array['Désirs alimentés chaque jour.','Comparaison et complexes.','Soutien financier indirect à ces contenus.']::text[], array['Tu suis des comptes que tu n''oserais pas montrer.','Ton fil d''actualité est rempli de corps exposés.']::text[], array['Se désabonner sans attendre.','Bloquer plutôt que masquer quand la tentation est forte.','S''abonner à des comptes bénéfiques pour rééduquer l''algorithme.']::text[], array['Faire le tri complet de tes abonnements.','Suivre trois comptes de rappels ou d''apprentissage.','Vérifier ton fil une semaine plus tard.']::text[], array['nur-30','nur-19']::text[], array['zina-yeux','delaisser-inutile']::text[], 'sens', 'Ce que tu enlèves de ton téléphone, Allah peut l''enlever de ton cœur. Fais de ton écran un lieu qui te rapproche de Lui.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('comptes-provocateurs', 'regard', 'Suivre des comptes provocateurs', 'Interdit lorsque le contenu suivi expose à ce qui est illicite', 'comptes-provocateurs', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('recherche-interdit', 'regard', 'Rechercher volontairement des contenus interdits', 'Quand ce n''est plus l''image qui vient à toi, mais toi qui vas vers elle.', 'Interdit — la recherche volontaire aggrave le péché', 'Il y a une différence entre croiser une image et taper soi-même une recherche. Le second cas est une décision, et c''est souvent là que l''on doit se poser des questions.', 'Il s''agit de chercher activement des contenus interdits : images, vidéos, discussions, comptes. L''intention et l''effort engagés rendent l''acte plus grave.', 'La recherche volontaire montre que le désir a pris le dessus sur la conscience. C''est le moment de réagir avant que l''habitude ne devienne une dépendance.', '« Le péché est ce qui trouble ton âme et que tu détestes que les gens découvrent. » Si tu effaces ton historique, c''est que ton cœur sait déjà.', 'Par l''ennui, la solitude ou une émotion forte, et par la facilité d''accès totale qu''offre Internet.', array['Dépendance et perte de contrôle.','Culpabilité et isolement.','Endurcissement progressif du cœur.']::text[], array['Tu utilises la navigation privée pour cela.','Tu effaces systématiquement ton historique.']::text[], array['Installer un filtre et confier le mot de passe à quelqu''un.','Se rappeler qu''Allah voit (50:16).','Quitter immédiatement le lieu ou l''écran dès que l''envie apparaît.']::text[], array['Installer un filtre aujourd''hui.','Désactiver la navigation privée si possible.','Préparer une liste d''actions de remplacement.']::text[], array['isra-36','anam-120','qaf-16']::text[], array['intention','peche-trouble']::text[], 'coeur-ferme', 'Le fait même que tu lises cet article prouve que ton cœur est vivant. Allah tend Sa main nuit et jour pour accueillir ton retour.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('recherche-interdit', 'regard', 'Rechercher volontairement des contenus interdits', 'Interdit — la recherche volontaire aggrave le péché', 'recherche-interdit', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('relations-amoureuses', 'relations', 'Les relations amoureuses hors mariage', '« On s''aime, on ne fait rien de mal »… le chemin commence souvent ainsi.', 'Interdites (haram) — relation hors cadre du mariage', 'Le « copain », la « copine », la relation « sérieuse » mais cachée : c''est devenu une norme pour beaucoup de jeunes musulmans, parfois même encouragée par l''entourage.', 'Il s''agit de toute relation sentimentale entre un homme et une femme non mariés : messages intimes, rencontres seul à seul, gestes affectifs. L''islam ne condamne pas les sentiments, mais encadre leur expression dans le mariage.', 'Ces relations rapprochent pas à pas de la fornication, ce qu''Allah interdit d''« approcher ». Elles laissent souvent des blessures profondes, des regrets et des familles brisées.', 'Le Coran parle des « pas de Shaytan » (24:21) : il ne pousse jamais directement au grand péché, mais par petites étapes. La relation « juste pour parler » est souvent le premier pas.', 'Par les réseaux, l''école, le travail ; par le besoin d''affection ; par l''influence des séries et des amis.', array['Rapprochement progressif de la fornication.','Mensonges envers les parents.','Blessures émotionnelles et dépendance affective.','Perte de la baraka dans un futur mariage.']::text[], array['Tu caches la relation à ta famille.','Vous vous voyez seuls.','Tu attends ses messages plus que l''heure de la prière.']::text[], array['Être honnête avec soi : cette relation ne plaît pas à Allah.','Y mettre fin clairement, ou l''orienter vers un mariage légitime en impliquant les familles.','Couper les canaux de contact privés.','Combler le vide par des activités, des amis pieux et l''adoration.']::text[], array['Écrire honnêtement ce que tu ressens et ce qu''Allah attend.','Parler à un proche de confiance ou à un imam.','Couper ou officialiser par la voie du mariage.','Remplir tes soirées d''activités saines.']::text[], array['isra-32','nur-30','nur-21']::text[], array['troisieme-shaytan','jeunes-mariage','zina-yeux']::text[], 'huda-afaf', 'Quitter une relation pour Allah est l''un des sacrifices les plus difficiles, et Il ne laisse jamais perdre ce qu''on abandonne pour Lui : « Tu ne laisseras pas une chose par crainte d''Allah sans qu''Il ne te donne mieux. »', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('relations-amoureuses', 'relations', 'Les relations amoureuses hors mariage', 'Interdites (haram) — relation hors cadre du mariage', 'relations-amoureuses', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('flirt', 'relations', 'Le flirt et la séduction', 'Un compliment, un regard appuyé, un message « gentil »… le jeu n''est jamais neutre.', 'Interdit entre personnes non mariées', 'Le flirt est souvent vu comme un jeu sans conséquence. Pourtant, il éveille le désir, crée des attachements et ouvre des portes que l''on ne sait plus refermer.', 'Il s''agit des paroles, attitudes et messages destinés à séduire ou à attirer l''attention d''une personne de l''autre sexe en dehors du mariage.', 'C''est l''une des premières marches vers les relations interdites. Il fait aussi naître des jalousies et des tromperies.', 'Le hadith explique que la langue aussi commet la « zina » par la parole. La pudeur, branche de la foi, se manifeste dans la manière de parler.', 'Par l''humour ambigu, les compliments répétés, les réactions aux stories.', array['Attachements interdits.','Perte de pudeur.','Conflits et trahisons.']::text[], array['Tu cherches à plaire à une personne précise.','Tes messages ont un double sens.']::text[], array['Garder un ton respectueux et professionnel.','Éviter les conversations privées inutiles.','Réagir moins aux publications personnelles.']::text[], array['Repérer les conversations ambiguës.','Les arrêter ou les rendre strictement utiles.','Faire du dhikr à la place de ces échanges.']::text[], array['isra-32','ahzab-35']::text[], array['zina-yeux','pudeur']::text[], 'huda-afaf', 'La vraie noblesse est dans la retenue. Celui qui préserve sa langue et son cœur pour Allah est honoré par Lui.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('flirt', 'relations', 'Le flirt et la séduction', 'Interdit entre personnes non mariées', 'flirt', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('conversations-intimes', 'relations', 'Les conversations intimes interdites', 'Il est minuit, l''écran est allumé, et personne ne sait à qui tu écris…', 'Interdites entre personnes non mariées', 'Les messageries ont créé un nouvel espace d''isolement : la conversation privée, souvent nocturne, qui devient de plus en plus intime.', 'Il s''agit d''échanges privés à caractère sentimental ou sexuel (textes, vocaux, photos, appels vidéo) entre personnes qui ne sont pas mariées.', 'C''est une forme numérique de l''isolement (khalwa) contre lequel le Prophète ﷺ a mis en garde. Les photos envoyées peuvent aussi être conservées et utilisées contre la personne.', 'Shaytan est « le troisième » dans l''isolement. Une conversation secrète la nuit réunit tous les éléments de cet isolement.', 'Par des messages d''abord banals, puis personnels, puis intimes.', array['Rapprochement de la fornication.','Risques de chantage et d''exposition.','Nuits blanches et prières manquées.']::text[], array['Tu caches ton écran.','Tu effaces des conversations.','Tu échanges surtout la nuit.']::text[], array['Mettre fin aux conversations privées concernées.','Ne jamais envoyer de photo intime.','Couper le téléphone à une heure fixe le soir.']::text[], array['Supprimer les contacts et conversations concernés.','Fixer un couvre-feu numérique.','Dormir après la prière d''Isha avec un dhikr du soir.']::text[], array['isra-32','qaf-16']::text[], array['troisieme-shaytan','peche-trouble']::text[], 'sens', 'Allah aime le serviteur qui revient vers Lui la nuit. Remplace ces conversations par un tête-à-tête avec ton Seigneur : quelques rakats, une invocation sincère.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('conversations-intimes', 'relations', 'Les conversations intimes interdites', 'Interdites entre personnes non mariées', 'conversations-intimes', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('infidelite', 'relations', 'L''infidélité', 'Elle commence rarement par une trahison… mais par une petite conversation.', 'Interdite (haram) — trahison de la confiance et péché grave', 'Messages à une autre personne, relation cachée, double vie numérique : l''infidélité détruit des foyers entiers.', 'L''infidélité désigne toute relation sentimentale ou sexuelle d''une personne mariée avec quelqu''un d''autre que son conjoint, y compris par écrans interposés.', 'Elle réunit la trahison de la confiance, le mensonge et le risque de l''adultère, l''un des grands péchés.', 'Trahir un dépôt est un trait de comportement hypocrite selon le hadith. Le mariage est un engagement solennel devant Allah.', 'Par la routine, les conflits non résolus, la recherche de nouveauté sur les réseaux.', array['Destruction de la confiance et de la famille.','Mensonges en chaîne.','Souffrance des enfants.']::text[], array['Tu caches ton téléphone à ton conjoint.','Tu confies à une autre personne ce que tu ne dis plus à ton conjoint.']::text[], array['Couper toute relation ambiguë immédiatement.','Se repentir sincèrement.','Travailler à reconstruire le couple, avec aide si nécessaire (médiation, imam, conseiller conjugal).']::text[], array['Couper le contact aujourd''hui.','Consacrer du temps de qualité à ton conjoint.','Demander conseil à une personne sage.']::text[], array['anfal-27','isra-32']::text[], array['hypocrite','zina-yeux']::text[], 'famille', 'Il n''est jamais trop tard pour protéger son foyer. Allah accepte le repentir et peut réparer ce qui semble brisé.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('infidelite', 'relations', 'L''infidélité', 'Interdite (haram) — trahison de la confiance et péché grave', 'infidelite', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('fornication', 'relations', 'La fornication (zina)', 'Le Coran ne dit pas seulement « ne la commettez pas », mais « ne vous en approchez pas ».', 'Grand péché (kabira) — interdiction formelle', 'La fornication est banalisée par la culture moderne, mais elle reste l''un des grands péchés en islam. Ceux qui l''ont commise doivent savoir que la porte du repentir reste ouverte.', 'La zina désigne les rapports sexuels entre un homme et une femme qui ne sont pas mariés l''un à l''autre.', 'Elle est qualifiée par Allah de « turpitude » et de « mauvais chemin ». Ses conséquences touchent l''âme, la famille, la société et les générations.', 'La sourate Al-Furqan mentionne la fornication parmi les grands péchés, puis ajoute immédiatement : « sauf celui qui se repent… Allah changera leurs mauvaises actions en bonnes ». L''avertissement et l''espoir vont ensemble.', 'Toujours par étapes : regards, paroles, rencontres, isolement.', array['Péché majeur à expier par un repentir sincère.','Souffrances psychologiques et sociales.','Risques sanitaires et familiaux.']::text[], array['Tu fréquentes des lieux et des personnes qui t''en rapprochent.','Tu acceptes l''isolement avec une personne non permise.']::text[], array['Fermer toutes les portes qui y mènent (regard, isolement, conversations).','Se repentir sincèrement : regret, arrêt, résolution.','Se couvrir : ne pas exposer son péché (Bukhari 6069).','Viser le mariage halal si possible, sinon le jeûne.']::text[], array['Rompre avec la situation à risque.','Faire ghusl, prier et demander pardon.','Changer d''environnement et de fréquentations.']::text[], array['isra-32','furqan-70','zumar-53']::text[], array['garantie-paradis','comme-sans-peche','jeunes-mariage']::text[], 'sayyid-istighfar', 'Aussi grave que soit le péché, la miséricorde d''Allah est plus grande. « Ne désespérez pas de la miséricorde d''Allah : Il pardonne tous les péchés. » Reviens, Il t''attend.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('fornication', 'relations', 'La fornication (zina)', 'Grand péché (kabira) — interdiction formelle', 'fornication', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('mauvaises-frequentations', 'relations', 'Les mauvaises fréquentations', 'Dis-moi qui tu fréquentes, et je te dirai vers où tu vas.', 'Il est obligatoire de s''éloigner de ce qui pousse au péché', 'Beaucoup de personnes ont commencé à fumer, à mentir, à manquer la prière ou à fréquenter des lieux interdits… à cause d''un groupe d''amis.', 'Ce sont les personnes qui encouragent le péché, se moquent de la pratique religieuse ou entraînent loin du rappel d''Allah.', 'L''influence de l''entourage est immense : « l''homme suit la religion de son ami intime ». Au Jour du Jugement, certains regretteront amèrement leurs amitiés.', 'Le Coran décrit l''injuste qui se mord les mains : « Si seulement je n''avais pas pris un tel pour ami ! » L''amitié est un choix qui engage l''au-delà.', 'Par le besoin d''appartenance, la peur d''être rejeté, l''habitude d''enfance.', array['Abandon progressif de la pratique.','Entraînement dans des péchés nouveaux.','Isolement des bonnes personnes.']::text[], array['Tu te sens mal à l''aise de prier devant eux.','Tu fais avec eux ce que tu ne ferais jamais seul.']::text[], array['Réduire progressivement le temps passé avec ces personnes.','Rechercher des amis pieux : mosquée, cercles de savoir, associations.','Rester poli et les inviter au bien quand c''est possible.']::text[], array['Lister tes fréquentations et leur influence.','Rejoindre une activité de la mosquée.','Planifier une sortie avec un ami pieux.']::text[], array['furqan-27','zukhruf-67','kahf-28']::text[], array['religion-ami','musc-forgeron']::text[], 'coeur-ferme', 'Choisir de meilleurs amis, c''est choisir son avenir. Allah t''enverra des compagnons qui te tireront vers le haut.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('mauvaises-frequentations', 'relations', 'Les mauvaises fréquentations', 'Il est obligatoire de s''éloigner de ce qui pousse au péché', 'mauvaises-frequentations', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('portes-relations', 'relations', 'Les comportements qui mènent aux relations interdites', 'Aucun grand péché n''arrive par hasard : il est toujours précédé de petites portes ouvertes.', 'Fermer les moyens qui mènent à l''interdit (sadd adh-dhara''i'')', 'Mixité sans retenue, isolement, messages privés, tenues provocantes, soirées : chacun semble anodin, mais ensemble ils forment un chemin.', 'Les savants parlent de « fermer les moyens » qui mènent à l''interdit. Ce qui conduit habituellement au péché doit être évité.', 'En banalisant les moyens, on se retrouve dans le péché sans l''avoir « décidé ».', '« Laisse ce qui te fait douter pour ce qui ne te fait pas douter. » La prudence est une forme de sagesse.', 'Par la confiance excessive en soi : « moi, je sais me contrôler ».', array['Exposition permanente à la tentation.','Glissement vers des relations interdites.']::text[], array['Tu te retrouves souvent seul avec une personne non permise.','Tu te justifies sans cesse.']::text[], array['Éviter l''isolement.','Limiter les échanges privés au strict nécessaire.','Garder une attitude digne et pudique.']::text[], array['Identifier une « porte » ouverte dans ta vie.','La fermer cette semaine.','Demander à Allah la fermeté.']::text[], array['nur-21','isra-32']::text[], array['troisieme-shaytan','laisse-doute']::text[], 'huda-afaf', 'Fermer une porte aujourd''hui, c''est s''épargner une grande peine demain. La prudence n''est pas de la faiblesse, c''est de la sagesse.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('portes-relations', 'relations', 'Les comportements qui mènent aux relations interdites', 'Fermer les moyens qui mènent à l''interdit (sadd adh-dhara''i'')', 'portes-relations', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('scrolling', 'reseaux', 'Le scrolling sans fin', '« Encore une vidéo »… et trois heures ont disparu.', 'Le gaspillage du temps est blâmable ; il devient interdit s''il fait manquer une obligation', 'Le défilement infini est conçu pour te garder le plus longtemps possible. Beaucoup passent plus de temps à scroller qu''à prier, lire ou parler à leur famille.', 'Le scrolling sans fin consiste à faire défiler des contenus sans but précis, souvent par automatisme.', 'Le temps est un capital dont nous serons interrogés. Le scrolling vole ce capital, disperse l''esprit et éloigne du rappel d''Allah.', '« Deux bienfaits dont beaucoup de gens sont lésés : la santé et le temps libre. » Le croyant « se détourne des futilités » (23:3).', 'Par l''ennui, la fatigue et la notification. Le cerveau s''habitue à la récompense rapide.', array['Perte de temps considérable.','Difficulté de concentration, notamment dans la prière.','Fatigue, sommeil perturbé.','Exposition continue aux tentations.']::text[], array['Tu ouvres une application sans savoir pourquoi.','Ton temps d''écran dépasse plusieurs heures par jour.']::text[], array['Mesurer son temps d''écran (outil intégré du téléphone).','Fixer des limites par application.','Désactiver les notifications non essentielles.','Remplacer par la lecture, la marche, le Coran.']::text[], array['Noter ton temps d''écran actuel.','Fixer une limite quotidienne.','Pas de téléphone 30 minutes avant de dormir.','Lire une page de Coran à la place du premier scroll du matin.']::text[], array['munafiqun-9','muminun-1','hadid-20']::text[], array['deux-bienfaits','pieds-bougeront','delaisser-inutile']::text[], 'dhikr-shukr', 'Chaque minute reprise au scrolling peut devenir une adoration. Commence petit : 15 minutes en moins par jour, c''est 90 heures gagnées par an.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('scrolling', 'reseaux', 'Le scrolling sans fin', 'Le gaspillage du temps est blâmable ; il devient interdit s''il fait manquer une obligation', 'scrolling', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('contenus-haram', 'reseaux', 'La consommation de contenus haram', 'Musique obscène, moqueries de la religion, indécence : ce que l''on consomme nous transforme.', 'Interdit pour les contenus clairement illicites ; certains sujets (comme la musique) font l''objet de divergences entre savants', 'On peut passer des heures à regarder des contenus que l''on n''oserait jamais regarder devant ses parents. Ce que l''on consomme forme nos goûts, nos valeurs et nos désirs.', 'Il s''agit de contenus clairement interdits : indécence, moquerie de la religion, incitation au péché, insultes. Sur certaines questions, comme la musique, les savants ont des avis différents : renseigne-toi auprès d''une personne de science.', 'Le cœur prend la couleur de ce qu''il absorbe. À force de rire de l''interdit, on ne le voit plus comme interdit.', 'Anas ibn Malik disait déjà à sa génération qu''elle considérait comme « plus fin qu''un cheveu » ce que les compagnons voyaient comme destructeur. La banalisation n''est pas nouvelle, mais elle est amplifiée aujourd''hui.', 'Par l''humour, les tendances, l''effet de groupe.', array['Perte de la sensibilité au mal.','Modification des valeurs.','Péchés de regard et d''écoute.']::text[], array['Tu ris de choses qui touchent à la religion.','Tu consommes ce que tu cacherais.']::text[], array['Faire un tri de ses abonnements.','Choisir des créateurs bénéfiques.','Se poser la question : « Aimerais-je qu''Allah me voie regarder ceci ? »']::text[], array['Supprimer trois sources de contenus problématiques.','Ajouter trois sources bénéfiques.','Faire le point dans une semaine.']::text[], array['nur-19','isra-36','anam-120']::text[], array['peches-meprises','plus-fin-cheveu']::text[], 'coeur-ferme', 'Ton cœur est précieux : nourris-le de ce qui l''élève. Ce que tu laisses pour Allah, Il te le remplace par mieux.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('contenus-haram', 'reseaux', 'La consommation de contenus haram', 'Interdit pour les contenus clairement illicites ; certains sujets (comme la musique) font l''objet de divergences entre savants', 'contenus-haram', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('perte-temps', 'reseaux', 'La perte de temps', 'Ta vie est faite de jours : quand un jour passe, une partie de toi s''en va.', 'Blâmable ; on sera interrogé sur l''usage de sa vie', 'Le temps est la chose la plus précieuse que nous possédons, et pourtant la plus gaspillée.', 'Perdre son temps, c''est le dépenser dans ce qui n''apporte aucun bénéfice dans ce monde ni dans l''autre, au détriment de ses obligations et de ses objectifs.', 'Le jour du Jugement, chacun sera interrogé sur sa vie et ce qu''il en a fait.', 'Le Coran décrit celui qui, à la mort, supplie de revenir pour faire le bien qu''il a délaissé. Le temps présent est l''occasion que l''on regrettera de ne pas avoir saisie.', 'Par l''absence d''objectifs, l''ennui et la procrastination.', array['Regrets.','Retard dans ses projets et sa pratique.','Sentiment de vide.']::text[], array['Tu finis tes journées sans avoir rien accompli.','Tu reportes sans cesse.']::text[], array['Fixer chaque jour trois objectifs (dont un spirituel).','Organiser sa journée autour des prières.','Réduire les distractions.']::text[], array['Écrire tes objectifs du mois.','Planifier ta journée autour des 5 prières.','Faire le bilan chaque soir.']::text[], array['muminun-99','takathur-1','hadid-20']::text[], array['pieds-bougeront','cinq-avant-cinq','deux-bienfaits']::text[], 'hamm', 'Tant que tu respires, il est temps. Le Prophète ﷺ a dit : « Profite de ta vie avant ta mort. » Commence aujourd''hui.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('perte-temps', 'reseaux', 'La perte de temps', 'Blâmable ; on sera interrogé sur l''usage de sa vie', 'perte-temps', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('validation', 'reseaux', 'La recherche permanente de validation', 'Combien de likes vaut ton cœur ?', 'L''ostentation (riya'') dans l''adoration est interdite ; la recherche excessive de l''approbation est blâmable', 'Publier pour être vu, compter les vues, se sentir mal sans réactions : la quête d''approbation est devenue une dépendance.', 'C''est le fait de faire dépendre son humeur, ses choix et même ses actes religieux du regard des autres.', 'Lorsqu''elle touche l''adoration, elle devient de l''ostentation, que le Prophète ﷺ a appelée « le petit shirk ». Elle crée aussi anxiété et complexes.', 'Allah ne regarde ni l''apparence ni le nombre d''abonnés, mais le cœur et les actions. Une action faite pour les gens perd sa valeur auprès d''Allah.', 'Par la mécanique des likes et la comparaison.', array['Anxiété et baisse de l''estime de soi.','Actes religieux faits pour être vus.','Exposition de sa vie privée.']::text[], array['Tu vérifies sans arrêt tes réactions.','Tu publies tes actes d''adoration pour être admiré.']::text[], array['Garder certaines bonnes actions secrètes.','Publier moins, vivre plus.','Renouveler son intention avant chaque publication.']::text[], array['Faire une bonne action secrète aujourd''hui.','Masquer le nombre de likes si possible.','Une journée sans publication par semaine.']::text[], array['hujurat-13','imran-185']::text[], array['ostentation','intention','coeurs-actions']::text[], 'dhikr-shukr', 'Le regard d''Allah suffit. Quand tu agis pour Lui seul, tu te libères du poids du regard des autres.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('validation', 'reseaux', 'La recherche permanente de validation', 'L''ostentation (riya'') dans l''adoration est interdite ; la recherche excessive de l''approbation est blâmable', 'validation', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('exposition-tentations', 'reseaux', 'L''exposition aux tentations', 'Tu ne cherches pas le péché… mais tu lui ouvres la porte chaque jour.', 'Il faut éviter de s''exposer volontairement à ce qui mène à l''interdit', 'Algorithmes, publicités, messages privés : les réseaux mettent la tentation à portée de pouce, à toute heure.', 'Il s''agit de s''exposer de façon répétée et évitable aux contenus et contacts qui poussent au péché.', 'La résistance s''use avec le temps. Celui qui s''expose sans cesse finit souvent par céder.', '« L''Enfer est entouré de désirs » : la tentation est attirante par nature. La sagesse est de ne pas jouer avec le feu.', 'Par la confiance excessive en sa force.', array['Chutes répétées.','Fatigue spirituelle.','Culpabilité.']::text[], array['Tu te retrouves souvent face à des contenus que tu regrettes.','Tu gardes des applications que tu sais dangereuses pour toi.']::text[], array['Supprimer les applications qui te font chuter.','Utiliser des versions limitées ou des filtres.','Ne pas utiliser son téléphone seul au lit.']::text[], array['Supprimer une application à risque.','Installer un filtre.','Remplacer par une application bénéfique (Coran, apprentissage).']::text[], array['yusuf-53','nur-21','imran-14']::text[], array['entoure-desirs','laisse-doute']::text[], 'taawudh', 'Se protéger, c''est se respecter. Allah récompense chaque porte que tu fermes pour Lui.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('exposition-tentations', 'reseaux', 'L''exposition aux tentations', 'Il faut éviter de s''exposer volontairement à ce qui mène à l''interdit', 'exposition-tentations', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('negligence-reseaux', 'reseaux', 'Négliger ses obligations à cause des réseaux', 'Le temps d''une vidéo… et l''heure de la prière est passée.', 'Retarder la prière au-delà de son temps sans excuse est un péché grave', 'Combien de prières ont été retardées ou manquées à cause d''une conversation, d''un jeu ou d''un live ?', 'Il s''agit de laisser les réseaux sociaux passer avant les obligations : prière, devoirs envers les parents, travail, études.', 'La prière est le lien entre le serviteur et son Seigneur. La négliger pour un écran, c''est inverser les priorités.', 'Allah avertit : « Que ni vos biens ni vos enfants ne vous distraient du rappel d''Allah. » Si cela vaut pour les biens et les enfants, que dire d''un écran ?', 'Par la phrase « je prie dans cinq minutes ».', array['Prières retardées ou manquées.','Relations familiales négligées.','Baisse des résultats et de la productivité.']::text[], array['Tu pries à la dernière minute.','Tu entends l''adhan sans bouger.']::text[], array['Poser le téléphone dès l''adhan.','Installer une application de rappel des prières.','Faire de la prière le point fixe de ta journée.']::text[], array['Activer les rappels de prière.','Poser le téléphone dès l''appel pendant 7 jours.','Suivre tes prières dans ton espace personnel.']::text[], array['munafiqun-9','ankabut-45','hashr-19']::text[], array['priere-heure','abandon-priere']::text[], 'dhikr-shukr', 'Allah t''attend cinq fois par jour. Chaque prière accomplie à l''heure est une victoire sur ton écran.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('negligence-reseaux', 'reseaux', 'Négliger ses obligations à cause des réseaux', 'Retarder la prière au-delà de son temps sans excuse est un péché grave', 'negligence-reseaux', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('prescriptions-vestimentaires', 'pudeur', 'Les prescriptions vestimentaires des hommes et des femmes', 'Le vêtement de la piété : voilà ce qui est meilleur.', 'Obligations avec des points de divergence reconnus entre savants', 'L''islam a donné des règles vestimentaires aux hommes comme aux femmes. Leur but n''est pas de contraindre, mais de préserver la dignité, la pudeur et le cœur.', 'Selon l''avis de la grande majorité des savants : la ''awra (partie à couvrir) de l''homme s''étend du nombril aux genoux ; celle de la femme devant les hommes non mahram comprend tout le corps, à l''exception du visage et des mains selon la majorité, certains savants incluant aussi le visage (question du niqab, objet de divergence reconnue). Le vêtement doit être ample, non transparent et non moulant. Il est interdit aux hommes de porter de l''or et de la soie. Il est interdit à chaque sexe d''imiter l''autre dans ce qui lui est propre.', 'Négliger ces règles expose à la tentation et va à l''encontre d''ordres explicites du Coran et de la Sunna.', 'Les versets 24:30-31 commencent par les hommes avant les femmes : la pudeur est une responsabilité partagée. Le hadith « vêtues mais nues » vise les vêtements transparents, moulants ou découvrants.', 'Par la mode, la pression sociale et le désir de plaire.', array['Exposition aux regards et à la tentation.','Désobéissance à un ordre explicite.','Affaiblissement de la pudeur intérieure.']::text[], array['Tes vêtements sont choisis pour attirer les regards.','Tu te sens gêné(e) de ta tenue devant des personnes pieuses.']::text[], array['Apprendre les règles auprès d''une personne de science.','Avancer par étapes sincères.','Renouveler son intention : s''habiller pour plaire à Allah.']::text[], array['Revoir ta garde-robe avec les critères : couvrant, ample, non transparent.','Remplacer une pièce problématique cette semaine.','Demander à Allah de t''aider à aimer la pudeur.']::text[], array['nur-30','nur-31','ahzab-59','araf-26']::text[], array['vetues-nues','or-soie','pudeur']::text[], 'huda-afaf', 'Chaque pas vers plus de pudeur est aimé d''Allah. Ne te compare pas aux autres : avance à ton rythme, avec sincérité.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('prescriptions-vestimentaires', 'pudeur', 'Les prescriptions vestimentaires des hommes et des femmes', 'Obligations avec des points de divergence reconnus entre savants', 'prescriptions-vestimentaires', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('hijab', 'pudeur', 'La négligence du hijab', 'Le hijab n''est pas un morceau de tissu… c''est une réponse à l''appel d''Allah.', 'Obligation (selon le consensus des savants) pour la femme musulmane pubère devant les hommes non mahram', 'Certaines le portent mal, d''autres l''enlèvent selon les lieux, d''autres encore pensent qu''il est « optionnel ». Ce sujet mérite douceur et clarté.', 'Le hijab désigne la couverture des cheveux et du corps de la femme selon les conditions mentionnées dans les versets. Le Coran ordonne de rabattre le khimar sur la poitrine (24:31) et de porter le jilbab (33:59).', 'Le négliger, c''est délaisser une obligation explicite. Mais celle qui ne le porte pas encore reste une sœur dans la foi, à accompagner avec bienveillance, jamais à humilier.', 'Le hijab protège la dignité et le cœur. Il est un acte d''adoration, et chaque jour où il est porté pour Allah est une récompense.', 'Par la pression sociale, la peur du regard des autres ou du manque d''emploi, et parfois par manque de connaissance.', array['Délaissement d''une obligation.','Exposition aux regards.','Affaiblissement progressif de la pudeur.']::text[], array['Tu l''enlèves selon les lieux.','Tu le portes de façon à ce qu''il ne couvre plus.']::text[], array['Apprendre le sens et les conditions du hijab.','S''entourer de sœurs qui encouragent.','Demander l''aide d''Allah et avancer avec patience.']::text[], array['Lire le tafsir des versets 24:31 et 33:59.','Parler avec une sœur de confiance.','Fixer une date et faire du du''a pour la fermeté.']::text[], array['nur-31','ahzab-59','araf-26']::text[], array['pudeur','pudeur-bien']::text[], 'coeur-ferme', 'Ton cheminement est précieux aux yeux d''Allah. Il ne regarde pas où tu en es, mais vers où tu avances.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('hijab', 'pudeur', 'La négligence du hijab', 'Obligation (selon le consensus des savants) pour la femme musulmane pubère devant les hommes non mahram', 'hijab', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('tenues', 'pudeur', 'Les tenues contraires aux prescriptions', 'Moulant, transparent, court : quand la mode décide à la place d''Allah.', 'Interdites lorsqu''elles ne respectent pas les conditions de la ''awra', 'Cela concerne aussi bien les hommes (shorts au-dessus des genoux, vêtements moulants, or et soie) que les femmes.', 'Une tenue est contraire aux prescriptions lorsqu''elle découvre la ''awra, qu''elle est transparente, moulante ou qu''elle imite l''autre sexe.', 'Elle expose au regard illicite et participe à la banalisation de l''indécence.', 'Le vêtement a deux fonctions selon le Coran : couvrir et embellir. Mais « le vêtement de la piété est meilleur ».', 'Par les tendances et l''envie de ressembler aux célébrités.', array['Désobéissance.','Attraction de regards illicites.','Perte progressive de la pudeur.']::text[], array['Tu choisis tes vêtements en fonction du regard des autres.']::text[], array['Appliquer des critères simples avant d''acheter : couvre, ample, opaque.','Trouver des marques modestes.']::text[], array['Trier ta garde-robe.','Adopter une règle d''achat claire.']::text[], array['araf-26','nur-31']::text[], array['vetues-nues','or-soie']::text[], 'huda-afaf', 'Tu peux être élégant(e) tout en respectant Allah : « Allah est Beau et Il aime la beauté. »', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('tenues', 'pudeur', 'Les tenues contraires aux prescriptions', 'Interdites lorsqu''elles ne respectent pas les conditions de la ''awra', 'tenues', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('manque-pudeur', 'pudeur', 'Le manque de pudeur (haya'')', 'Quand plus rien ne gêne, c''est le cœur qui est en danger.', 'La pudeur est une branche de la foi ; son absence ouvre la porte à tous les excès', 'La pudeur ne concerne pas que le vêtement : elle touche la parole, le comportement, les publications et le rapport à Allah.', 'Le haya'' est un sentiment intérieur qui pousse à éviter ce qui est laid et à respecter les droits d''Allah et des gens.', 'Sans pudeur, plus rien ne retient. Le hadith la place au cœur même de la foi.', 'La pudeur envers Allah consiste à se souvenir qu''Il voit tout, même dans la solitude.', 'Par l''exposition, l''humour vulgaire et la course à l''attention.', array['Paroles et comportements vulgaires.','Exposition de sa vie intime.','Perte du respect des autres.']::text[], array['Tu racontes tes péchés.','Tu ne ressens plus de gêne.']::text[], array['Se rappeler qu''Allah voit.','Choisir ses mots.','Moins s''exposer en ligne.']::text[], array['Supprimer une publication indécente.','Une semaine sans gros mots.','Méditer sur le nom d''Allah « Ar-Raqib » (l''Observateur).']::text[], array['araf-26','qaf-16']::text[], array['pudeur','pudeur-bien','mujahirin']::text[], 'akhlaq', 'La pudeur n''apporte que du bien. Chaque jour, tu peux la cultiver un peu plus.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('manque-pudeur', 'pudeur', 'Le manque de pudeur (haya'')', 'La pudeur est une branche de la foi ; son absence ouvre la porte à tous les excès', 'manque-pudeur', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('modestie', 'pudeur', 'La négligence de la modestie', 'Montrer, briller, impressionner… à quel prix ?', 'L''ostentation et la vanité sont blâmables ; l''orgueil est un grand péché', 'Exhiber ses biens, son corps ou sa réussite est devenu un mode de vie pour beaucoup sur les réseaux.', 'La modestie est l''attitude de celui qui ne cherche pas à se mettre en avant et reste humble dans sa tenue, ses paroles et sa manière de vivre.', 'La vanité peut glisser vers l''orgueil et l''ostentation.', '« Nul ne s''humilie pour Allah sans qu''Allah ne l''élève. » La vraie élévation vient de l''humilité.', 'Par la comparaison et la culture du paraître.', array['Vanité, jalousie suscitée chez les autres.','Ostentation dans les actes.']::text[], array['Tu publies surtout pour montrer.']::text[], array['Remercier Allah en secret pour ses bienfaits.','Réduire l''exhibition.']::text[], array['Une semaine sans publier tes achats.','Une aumône discrète.']::text[], array['luqman-18','hujurat-13']::text[], array['sadaqa-diminue','orgueil']::text[], 'akhlaq', 'L''humilité est une parure invisible, mais elle élève auprès d''Allah.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('modestie', 'pudeur', 'La négligence de la modestie', 'L''ostentation et la vanité sont blâmables ; l''orgueil est un grand péché', 'modestie', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('encourager-indecence', 'pudeur', 'Les comportements qui encouragent l''indécence', 'Un like, un partage, un rire… et l''indécence gagne du terrain.', 'Participer à la propagation de la turpitude est interdit', 'On peut ne pas commettre soi-même un péché, et pourtant le diffuser, l''applaudir ou le normaliser.', 'Cela comprend le fait de partager, liker, encourager ou défendre des contenus et des comportements indécents.', 'Le Coran menace d''un châtiment ceux qui aiment voir la turpitude se répandre parmi les croyants.', 'Le simple fait d''« aimer » que la turpitude se propage est condamné (24:19). Nos réactions en ligne sont des actes.', 'Par l''effet de mode et l''humour.', array['Péché collectif.','Normalisation du mal.']::text[], array['Tu partages des contenus indécents « pour rire ».']::text[], array['Ne pas réagir aux contenus indécents.','Partager du bien à la place.']::text[], array['Partager un rappel bénéfique cette semaine.','Retirer tes likes de contenus problématiques.']::text[], array['nur-19','nahl-90']::text[], array['mujahirin','peches-meprises']::text[], 'akhlaq', 'Tu peux devenir une source de bien en ligne : chaque bien partagé te sera compté.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('encourager-indecence', 'pudeur', 'Les comportements qui encouragent l''indécence', 'Participer à la propagation de la turpitude est interdit', 'encourager-indecence', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('mensonge', 'comportement', 'Le mensonge', '« Ce n''est qu''un petit mensonge »… mais il en appelle toujours un autre.', 'Interdit (haram), avec des exceptions très limitées précisées par les savants', 'Mensonges pour éviter un problème, pour faire rire, pour se valoriser : on ment parfois sans même s''en rendre compte.', 'Le mensonge consiste à dire volontairement le contraire de la vérité.', 'Le mensonge guide vers la perversité, et la perversité vers le Feu. C''est aussi un des signes de l''hypocrisie.', 'Le hadith montre un enchaînement : chaque mensonge facilite le suivant jusqu''à ce que la personne soit inscrite auprès d''Allah comme menteuse.', 'Par la peur, la facilité et l''habitude dès l''enfance.', array['Perte de confiance.','Enchaînement de mensonges.','Affaiblissement de la foi.']::text[], array['Tu inventes des excuses facilement.','Tu exagères tes histoires.']::text[], array['S''engager à dire la vérité même quand elle coûte.','Réfléchir avant de parler.','Réparer les mensonges passés si possible.']::text[], array['Une journée de vérité totale.','Noter chaque tentation de mentir.','Demander pardon pour un mensonge ancien.']::text[], array['tawba-119','saff-2']::text[], array['verite','hypocrite']::text[], 'akhlaq', 'La véracité guide vers le Paradis. Chaque vérité dite pour Allah renforce ta foi.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('mensonge', 'comportement', 'Le mensonge', 'Interdit (haram), avec des exceptions très limitées précisées par les savants', 'mensonge', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('medisance', 'comportement', 'La médisance (ghiba)', 'Le péché le plus facile à commettre… et l''un des plus lourds.', 'Interdite (haram) — considérée par de nombreux savants comme un grand péché', 'Entre amis, en famille, au travail, dans les groupes de discussion : parler des absents est devenu un loisir.', 'La médisance, selon la définition du Prophète ﷺ, consiste à mentionner son frère en son absence par ce qu''il déteste, même si c''est vrai. Si c''est faux, c''est de la calomnie.', 'Le Coran la compare à manger la chair de son frère mort. Elle détruit les liens et les bonnes actions.', 'La comparaison du Coran est volontairement choquante pour réveiller la conscience : on ne ressent rien en médisant, mais la réalité de l''acte est répugnante.', 'Par l''ennui, la jalousie et le besoin de se sentir supérieur.', array['Destruction de la fraternité.','Perte des bonnes actions.','Atteinte à l''honneur d''autrui.']::text[], array['Tes conversations tournent souvent autour des autres.']::text[], array['Changer de sujet ou défendre l''absent.','Quitter une assemblée de médisance.','Faire du du''a pour la personne dont on a médit.']::text[], array['Une journée sans parler d''absents.','Défendre quelqu''un qui est critiqué.','Réciter l''expiation de l''assemblée à la fin des réunions.']::text[], array['hujurat-12','humaza-1']::text[], array['medisance','bien-ou-silence','musulman-langue']::text[], 'kaffara-majlis', 'Préserver sa langue, c''est préserver son Paradis. Chaque parole retenue pour Allah est une adoration.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('medisance', 'comportement', 'La médisance (ghiba)', 'Interdite (haram) — considérée par de nombreux savants comme un grand péché', 'medisance', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('insultes', 'comportement', 'Les insultes et la grossièreté', 'Les mots blessent plus longtemps que les coups.', 'Interdites — insulter le musulman est une perversité', 'Les insultes sont devenues banales dans les conversations, les jeux en ligne et même entre amis « pour rire ».', 'Il s''agit des injures, moqueries, malédictions et propos vulgaires.', '« Insulter le musulman est une perversité. » Le croyant n''est pas grossier ni obscène.', 'Allah ordonne de dire « les meilleures paroles », car Shaytan sème la discorde par les mots.', 'Par l''environnement et les jeux en ligne.', array['Conflits.','Langue souillée.','Mauvaise image de l''islam.']::text[], array['Tu insultes sans même t''en rendre compte.']::text[], array['Remplacer les gros mots par le dhikr.','Se taire sous la colère.','S''excuser après un écart.']::text[], array['Une semaine sans insultes.','Une pièce donnée en aumône à chaque écart.']::text[], array['hujurat-11','isra-53']::text[], array['insulte','pas-croyant-grossier','bien-ou-silence']::text[], 'akhlaq', 'Ta langue peut devenir une source de lumière : un mot gentil est une aumône.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('insultes', 'comportement', 'Les insultes et la grossièreté', 'Interdites — insulter le musulman est une perversité', 'insultes', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('orgueil', 'comportement', 'L''orgueil (kibr)', 'Le premier péché commis contre Allah fut un péché d''orgueil.', 'Grand péché', 'Iblis a refusé de se prosterner par orgueil. Aujourd''hui, l''orgueil se cache dans le refus d''un conseil, le mépris des autres ou la certitude d''avoir toujours raison.', 'Le Prophète ﷺ a défini l''orgueil : « rejeter la vérité et mépriser les gens ». Prendre soin de son apparence n''est pas de l''orgueil.', '« N''entrera pas au Paradis celui qui a dans son cœur le poids d''un atome d''orgueil. »', 'La définition prophétique donne un test simple : est-ce que j''accepte la vérité quand elle vient d''un autre ? Est-ce que je méprise des gens ?', 'Par la réussite, le savoir, la beauté ou la richesse.', array['Refus de la vérité.','Mépris des autres.','Éloignement d''Allah.']::text[], array['Tu n''acceptes pas la critique.','Tu te sens supérieur aux autres.']::text[], array['Accepter les conseils.','Servir les autres.','Méditer sur son origine et sa fin.']::text[], array['Demander un conseil à quelqu''un.','Rendre un service discret.','Saluer en premier ceux que tu ignores.']::text[], array['luqman-18','hujurat-13']::text[], array['orgueil','sadaqa-diminue']::text[], 'akhlaq', 'S''humilier devant Allah élève. Celui qui se remet en question est déjà sur la bonne voie.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('orgueil', 'comportement', 'L''orgueil (kibr)', 'Grand péché', 'orgueil', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('jalousie', 'comportement', 'La jalousie (hasad)', 'Elle ronge celui qui la porte bien avant de toucher celui qu''elle vise.', 'Le hasad (souhaiter la disparition d''un bienfait chez autrui) est interdit', 'Jalousie de la réussite d''un ami, du mariage d''une sœur, de la beauté ou de l''argent d''un autre : elle est fréquente et souvent cachée.', 'Le hasad consiste à souhaiter qu''un bienfait disparaisse chez autrui. Il se distingue de la ghibta (souhaiter avoir la même chose sans vouloir qu''il la perde), qui est permise dans le bien.', 'C''est une contestation de la répartition d''Allah et une maladie du cœur qui mène à la médisance, à la haine et à l''injustice.', 'Le remède prophétique est d''aimer pour son frère ce qu''on aime pour soi-même.', 'Par la comparaison constante, notamment sur les réseaux.', array['Tristesse permanente.','Haine et conflits.','Médisance.']::text[], array['La réussite des autres te rend triste.','Tu cherches leurs défauts.']::text[], array['Faire du du''a pour la personne enviée.','Réduire les comparaisons.','Remercier Allah pour ses propres bienfaits.']::text[], array['Écrire dix bienfaits dont tu jouis.','Faire une invocation sincère pour quelqu''un que tu envies.','Le féliciter sincèrement.']::text[], array['nisa-54','falaq-5','hashr-10']::text[], array['pas-envie','aimer-frere']::text[], 'sans-rancoeur', 'Un cœur pur de jalousie est un cœur libre. Chaque du''a pour autrui fait dire aux anges : « Et toi de même. »', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('jalousie', 'comportement', 'La jalousie (hasad)', 'Le hasad (souhaiter la disparition d''un bienfait chez autrui) est interdit', 'jalousie', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('injustice', 'comportement', 'L''injustice', 'Elle sera des ténèbres le Jour de la Résurrection.', 'Interdite (haram)', 'Prendre un droit, mal traiter un employé, tricher, frapper, dénigrer : l''injustice prend de nombreuses formes.', 'L''injustice (dhulm) consiste à porter atteinte au droit d''autrui ou à mettre une chose à une place qui n''est pas la sienne.', 'Les droits des gens ne sont pas effacés par le seul repentir envers Allah : il faut les restituer ou obtenir le pardon de la personne.', 'Même la haine envers un groupe ne justifie pas l''injustice (5:8). La justice est un ordre absolu.', 'Par le pouvoir, l''avidité ou la colère.', array['Ténèbres le Jour du Jugement.','Invocation de l''opprimé exaucée.','Rancœurs et conflits.']::text[], array['Tu profites de ta position pour obtenir ce qui ne t''appartient pas.']::text[], array['Restituer les droits.','Demander pardon aux personnes lésées.','Être juste même contre soi.']::text[], array['Identifier un droit à rendre.','Le rendre ou demander pardon cette semaine.']::text[], array['nisa-135','maida-8','nahl-90']::text[], array['injustice','pas-envie']::text[], 'adam', 'Réparer une injustice ici-bas est infiniment plus léger qu''au Jour du Jugement. Le courage de réparer est aimé d''Allah.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('injustice', 'comportement', 'L''injustice', 'Interdite (haram)', 'injustice', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('parents', 'comportement', 'Le manque de respect envers les parents', 'Un simple « Fi ! » est déjà interdit…', 'La désobéissance aux parents est un des plus grands péchés', 'Ton méprisant, cris, ignorance de leurs appels, oubli de leurs besoins : beaucoup ne réalisent pas la gravité de ces comportements.', 'Il s''agit de tout manque de bienfaisance envers les parents : paroles dures, désobéissance dans ce qui est permis, abandon, ingratitude.', 'La désobéissance aux parents est citée juste après l''association à Allah parmi les plus grands péchés.', 'Le Coran interdit même de leur dire « Fi » (l''expression d''agacement la plus légère). La bonté envers eux est l''une des œuvres les plus aimées d''Allah.', 'Par la fatigue, l''adolescence, les conflits de génération.', array['Grand péché.','Perte de la baraka.','Regrets après leur départ.']::text[], array['Tu soupires quand ils t''appellent.','Tu élèves la voix contre eux.']::text[], array['Parler avec douceur.','Les servir sans attendre qu''ils demandent.','Faire des invocations pour eux.']::text[], array['Appeler ou visiter tes parents.','Leur rendre un service.','Réciter chaque jour l''invocation pour eux.']::text[], array['isra-23']::text[], array['grands-peches','mere-trois','priere-heure']::text[], 'parents', 'Tes parents sont une porte du Paradis. Tant qu''ils sont là, chaque jour est une occasion de la franchir.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('parents', 'comportement', 'Le manque de respect envers les parents', 'La désobéissance aux parents est un des plus grands péchés', 'parents', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('humiliation', 'comportement', 'Humilier les autres', 'Il suffit comme mal pour une personne de mépriser son frère.', 'Interdit', 'Moqueries, surnoms blessants, humiliations publiques, vidéos « drôles » aux dépens de quelqu''un : la cruauté est souvent déguisée en humour.', 'Humilier, c''est rabaisser une personne par la parole, le geste ou la publication.', 'Le Coran interdit de se moquer d''un groupe : « ceux-ci sont peut-être meilleurs qu''eux ».', 'Le plus noble auprès d''Allah est le plus pieux, et seul Allah connaît la piété des cœurs.', 'Par l''effet de groupe et le besoin de paraître drôle.', array['Blessures profondes chez autrui.','Péché lié aux droits des gens.']::text[], array['Tu ris des défauts des autres.']::text[], array['Arrêter les moqueries.','Présenter ses excuses.','Valoriser les autres.']::text[], array['S''excuser auprès d''une personne blessée.','Faire un compliment sincère.']::text[], array['hujurat-11','hujurat-13']::text[], array['pas-envie','musulman-langue']::text[], 'akhlaq', 'Celui qui préserve la dignité des autres, Allah préserve la sienne.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('humiliation', 'comportement', 'Humilier les autres', 'Interdit', 'humiliation', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('trahison', 'comportement', 'La trahison', 'Une confiance trahie ne se répare pas en un jour.', 'Interdite (haram)', 'Révéler un secret, ne pas tenir sa promesse, détourner un dépôt : la trahison prend mille visages.', 'La trahison consiste à manquer à la confiance placée en soi, qu''il s''agisse d''un bien, d''un secret ou d''un engagement.', 'C''est l''un des signes de l''hypocrisie selon le hadith.', 'La fidélité aux engagements fait partie de la foi. Allah interdit de « trahir sciemment ».', 'Par l''intérêt personnel et la facilité.', array['Perte de confiance.','Conflits.','Signe d''hypocrisie.']::text[], array['Tu révèles des secrets.','Tu ne tiens pas tes promesses.']::text[], array['Tenir ses engagements.','Garder les secrets.','Rendre les dépôts.']::text[], array['Tenir une promesse en suspens.','Rendre ce qui ne t''appartient pas.']::text[], array['anfal-27']::text[], array['hypocrite']::text[], 'akhlaq', 'Être digne de confiance est une qualité des prophètes. Tu peux la retrouver dès aujourd''hui.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('trahison', 'comportement', 'La trahison', 'Interdite (haram)', 'trahison', 'review') on conflict (id) do nothing;
insert into public.articles (slug, category_id, titre, accroche, hukm, intro, explication, danger, comprendre, installation, consequences, signes, abandon, plan, verset_ids, hadith_ids, invocation_id, encouragement, status, created_by) values ('mauvaise-intention', 'comportement', 'La mauvaise intention', 'Deux personnes font le même geste… et n''ont pas la même récompense.', 'L''intention détermine la valeur des actes', 'Prier pour être vu, aider pour être remercié, donner pour être admiré : l''intention se corrompt souvent sans bruit.', 'L''intention est ce que le cœur vise réellement. Une bonne action faite pour autre chose qu''Allah perd sa valeur auprès de Lui.', 'L''ostentation est appelée « le petit shirk ». Elle peut annuler la récompense des actes.', 'Allah regarde les cœurs et les actions. Renouveler son intention transforme même les gestes ordinaires (manger, dormir, travailler) en adoration.', 'Par le désir de reconnaissance.', array['Perte de la récompense.','Fatigue spirituelle.']::text[], array['Tu es déçu quand personne ne remarque tes bonnes actions.']::text[], array['Renouveler son intention avant chaque acte.','Faire des œuvres secrètes.','Demander à Allah la sincérité.']::text[], array['Choisir une bonne action secrète par jour.','Dire « pour Allah » intérieurement avant d''agir.']::text[], array['hujurat-13','zalzala-7']::text[], array['intention','ostentation','coeurs-actions']::text[], 'dhikr-shukr', 'La sincérité se travaille toute la vie. Le simple fait de t''en soucier est un signe de foi.', 'review', null) on conflict (slug) do nothing;
insert into public.sins (id, category_id, nom, hukm, article_slug, status) values ('mauvaise-intention', 'comportement', 'La mauvaise intention', 'L''intention détermine la valeur des actes', 'mauvaise-intention', 'review') on conflict (id) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (1, 1, 'Faire le point honnêtement', 'Le changement commence par la vérité sur soi.', 'rad-11', 'intention', 'Allah ne change pas l''état d''une personne tant qu''elle ne change pas ce qui est en elle. Ce programme commence par une intention sincère : le faire pour Allah.', 'Écris (dans ton espace privé) trois habitudes que tu veux changer, et formule ton intention.', 'coeur-ferme', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (2, 1, 'Observer tes journées', 'On ne change que ce que l''on voit.', 'isra-36', 'pieds-bougeront', 'Nous serons interrogés sur notre vie. Observer sa journée, c''est commencer à en prendre la responsabilité.', 'Note à quels moments de la journée tu te sens le plus loin d''Allah.', 'dhikr-shukr', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (3, 1, 'Repérer tes déclencheurs', 'Chaque habitude a un déclencheur.', 'yusuf-53', 'peche-trouble', 'L''âme incite au mal. Repérer ce qui la pousse (fatigue, solitude, écran, personnes) permet d''agir avant la chute.', 'Pour chaque habitude notée au jour 1, écris son déclencheur principal.', 'taawudh', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (4, 1, 'Mesurer ton temps', 'Le temps est un capital confié.', 'takathur-1', 'deux-bienfaits', 'Beaucoup sont lésés dans leur temps libre. Savoir où il part est le premier pas pour le reprendre.', 'Consulte ton temps d''écran et note-le.', 'hamm', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (5, 1, 'Choisir ton premier combat', 'Mieux vaut une victoire durable que dix tentatives abandonnées.', 'baqara-286', 'regularite', 'Allah n''impose pas plus que la capacité. Commencer par un seul objectif rend le changement possible.', 'Choisis l''habitude prioritaire à changer pendant ce programme.', 'huda-afaf', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (6, 2, 'Nettoyer ton téléphone', 'Fermer les portes avant de lutter.', 'nur-21', 'laisse-doute', 'Shaytan avance pas à pas ; on se protège en fermant les premiers pas.', 'Supprime au moins une application ou cinq abonnements qui t''éloignent d''Allah.', 'sens', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (7, 2, 'Baisser le regard', 'Le regard est la porte du cœur.', 'nur-30', 'regard-ali', 'Le premier regard involontaire est pardonné ; le second est un choix. Aujourd''hui, entraîne-toi à détourner immédiatement.', 'Pratique la règle du « premier regard » toute la journée, dans la rue et sur l''écran.', 'sens', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (8, 2, 'Protéger tes nuits', 'La nuit est le moment des chutes… et des plus belles adorations.', 'isra-32', 'troisieme-shaytan', 'L''isolement est le terrain de Shaytan. Le soir, éloigne ce qui te met en danger.', 'Laisse ton téléphone hors de la chambre cette nuit.', 'tawakkul-sortie', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (9, 2, 'Remplacer plutôt que lutter', 'Un vide se remplit toujours.', 'hud-114', 'crains-allah', 'Les bonnes actions dissipent les mauvaises. Prévois une bonne action à la place de chaque moment à risque.', 'Écris une alternative pour chacun de tes déclencheurs.', 'dhikr-shukr', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (10, 2, 'Sortir de l''isolement', 'On ne tient pas longtemps seul.', 'kahf-28', 'musc-forgeron', 'Le bon compagnon est comme le vendeur de musc. On ne tient pas seul longtemps.', 'Contacte une personne pieuse ou rends-toi à la mosquée.', 'coeur-ferme', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (11, 3, 'Comprendre le repentir', 'La tawbah n''est pas une honte, c''est une adoration.', 'tahrim-8', 'repentants', 'Les meilleurs de ceux qui commettent des fautes sont ceux qui se repentent.', 'Lis la page « Repentir » et ses quatre conditions.', 'astaghfirullah', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (12, 3, 'Ta première tawbah sincère', 'Regretter, arrêter, décider.', 'imran-135', 'regret', '« Le regret est repentir. » Ceux qui demandent pardon et ne persistent pas sont loués par Allah.', 'Fais deux rakats puis demande pardon à Allah pour tes péchés passés, sans désespoir.', 'sayyid-istighfar', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (13, 3, '100 istighfar', 'Le Prophète ﷺ demandait pardon plus de 70 fois par jour.', 'nisa-110', 'soixante-dix', 'Celui qui demande pardon trouve Allah Pardonneur et Miséricordieux.', 'Dis « Astaghfirullah » 100 fois aujourd''hui (utilise le compteur de dhikr).', 'astaghfirullah', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (14, 3, 'Rendre un droit', 'Certains péchés touchent les autres.', 'nisa-135', 'injustice', 'Les droits des gens doivent être rendus ou pardonnés. L''injustice sera ténèbres au Jour dernier.', 'Demande pardon à une personne que tu as blessée, ou rends ce qui ne t''appartient pas.', 'adam', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (15, 3, 'Chasser le désespoir', 'Aucun péché n''est plus grand que la miséricorde d''Allah.', 'zumar-53', 'nuages-ciel', 'Même si tes péchés atteignaient les nuages du ciel, Allah pardonne à celui qui revient.', 'Lis et médite le verset 39:53. Écris ce qu''il change pour toi.', 'yunus', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (16, 4, 'La prière à l''heure', 'L''œuvre la plus aimée d''Allah.', 'ankabut-45', 'priere-heure', 'La prière préserve de la turpitude. Elle est la protection quotidienne du croyant.', 'Prie les cinq prières à l''heure et coche-les dans ton suivi.', 'dhikr-shukr', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (17, 4, 'Le dhikr après la prière', 'Des paroles légères, lourdes dans la balance.', 'baqara-152', 'tasbih-priere', 'Souvenez-vous de Moi, Je Me souviendrai de vous.', 'Après chaque prière : 33 Subhan Allah, 33 Al-hamdu lillah, 33 Allahu akbar.', 'deux-paroles', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (18, 4, 'Le Coran chaque jour', 'Le meilleur d''entre vous apprend le Coran.', 'muhammad-24', 'meilleur-coran', 'Le Coran se lit et se médite. Quelques versets compris valent mieux que des pages lues sans attention.', 'Lis une page du Coran avec sa traduction.', 'ne-pas-devier', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (19, 4, 'Le dhikr du matin et du soir', 'Le dhikr est la vie du cœur.', 'rad-28', 'vivant-mort', 'C''est par l''évocation d''Allah que les cœurs se tranquillisent.', 'Fais ton dhikr du matin et du soir.', 'tawakkul-sortie', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (20, 4, 'Une prière surérogatoire', 'Se rapprocher par les nawafil.', 'imran-31', 'rapprocher-nawafil', 'Le serviteur se rapproche d''Allah par les œuvres surérogatoires jusqu''à ce qu''Il l''aime.', 'Ajoute deux rakats (par exemple la sunna du Fajr ou deux rakats la nuit).', 'dhikr-shukr', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (21, 5, 'Faire le tri dans tes fréquentations', 'On suit la religion de son ami.', 'furqan-27', 'religion-ami', 'Certains regretteront au Jour dernier d''avoir pris un tel pour ami.', 'Identifie une fréquentation qui t''éloigne et une qui te rapproche d''Allah.', 'coeur-ferme', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (22, 5, 'Préserver ta langue', 'Dire du bien ou se taire.', 'hujurat-12', 'bien-ou-silence', 'La médisance est comparée à manger la chair de son frère mort.', 'Une journée entière sans médisance ni moquerie.', 'kaffara-majlis', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (23, 5, 'Honorer tes parents', 'Ta mère, ta mère, ta mère, puis ton père.', 'isra-23', 'mere-trois', 'La bonté envers les parents vient juste après la prière dans les œuvres les plus aimées.', 'Rends un service à tes parents ou appelle-les, et invoque pour eux.', 'parents', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (24, 5, 'Maîtriser ta colère', 'Le fort est celui qui se maîtrise.', 'imran-134', 'fort-colere', 'Ceux qui maîtrisent leur colère et pardonnent sont aimés d''Allah.', 'Au premier signe de colère : « A''udhu billah », silence, ablutions.', 'taawudh', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (25, 5, 'Un bienfait envers quelqu''un', 'Aucun bien n''est petit.', 'fussilat-34', 'sourire', 'Repousser le mal par le bien transforme les cœurs.', 'Fais une bonne action envers quelqu''un (aide, sourire, aumône).', 'akhlaq', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (26, 6, 'Relire ton parcours', 'Mesurer le chemin parcouru donne la force de continuer.', 'zalzala-7', 'regularite', 'Aucun atome de bien n''est perdu. Chaque effort de ces 25 jours est enregistré.', 'Relis tes bilans quotidiens et note tes progrès.', 'dhikr-shukr', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (27, 6, 'Préparer les rechutes', 'Tomber n''est pas échouer ; ne pas se relever l''est.', 'imran-135', 'main-tendue', 'Allah tend Sa main nuit et jour pour accueillir le repentir.', 'Écris ton plan en cas de rechute : quoi faire dans les 10 minutes qui suivent.', 'sayyid-istighfar', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (28, 6, 'La gratitude', 'La reconnaissance augmente les bienfaits.', 'ibrahim-7', 'croyant-etonnant', 'Si vous êtes reconnaissants, J''augmenterai pour vous.', 'Écris dix bienfaits d''Allah dans ta vie.', 'dhikr-shukr', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (29, 6, 'Une sadaqa', 'L''aumône ne diminue pas les biens.', 'baqara-261', 'sadaqa-diminue', 'La dépense dans le bien est multipliée comme un grain qui donne sept épis.', 'Fais une aumône, même petite, avec une intention sincère.', 'dunya-akhira', 'review') on conflict (jour) do nothing;
insert into public.daily_programs (jour, phase, mission, enseignement, verset_id, hadith_id, explication, action, invocation_id, status) values (30, 6, 'Préparer la suite', 'La persévérance est le vrai succès.', 'ankabut-69', 'laisse-pour-allah', 'Allah guide sur Ses chemins ceux qui luttent pour Lui. Ce que tu as laissé pour Lui, Il le remplace par mieux.', 'Choisis tes trois habitudes à garder et le prochain combat à mener. Tu peux recommencer le programme.', 'coeur-ferme', 'review') on conflict (jour) do nothing;
